"""Textes de la Citadelle (suite) : les leçons cit6 à cit11."""
L = ["fr", "en", "es", "de", "it", "pt", "ru", "zh", "ja", "hi", "ar", "bn", "id", "ur"]


def T(*v):
    assert len(v) == 14, v[0]
    return dict(zip(L, v))


K = {
 # ------------------------------------------------------------------ cit6 le cheval de Troie
 "hist.cit6.0.dit": T("Un cadeau est arrivé : cadeau.sh. Avant de lancer un programme, on le LIT.", "A present arrived: cadeau.sh. Before running a program, we READ it.", "Llegó un regalo: cadeau.sh. Antes de ejecutar un programa, lo LEEMOS.", "Ein Geschenk ist da: cadeau.sh. Bevor man ein Programm startet, LIEST man es.", "È arrivato un regalo: cadeau.sh. Prima di lanciare un programma, lo LEGGIAMO.", "Chegou um presente: cadeau.sh. Antes de rodar um programa, a gente o LÊ.", "Пришёл подарок: cadeau.sh. Прежде чем запускать программу, её ЧИТАЮТ.", "来了个礼物：cadeau.sh。运行程序之前，先读一读。", "プレゼントが届いた：cadeau.sh。プログラムは実行する前に読む。", "एक तोहफ़ा आया: cadeau.sh। प्रोग्राम चलाने से पहले उसे पढ़ते हैं।", "وصلت هدية: cadeau.sh. قبل تشغيل أي برنامج، نقرؤه.", "একটা উপহার এসেছে: cadeau.sh। প্রোগ্রাম চালানোর আগে পড়ে নিই।", "Ada hadiah datang: cadeau.sh. Sebelum menjalankan program, kita MEMBACANYA.", "ایک تحفہ آیا: cadeau.sh۔ پروگرام چلانے سے پہلے اسے پڑھتے ہیں۔"),
 "hist.cit6.0.bravo": T("Il dit « Lance-moi vite ! »… mais plus bas, il y a un rm. C'est un cheval de Troie !", "It says “Run me quickly!”… but further down there is an rm. It's a Trojan horse!", "Dice «¡Ejecútame rápido!»… pero más abajo hay un rm. ¡Es un caballo de Troya!", "Es sagt „Starte mich schnell!“ … aber weiter unten steht ein rm. Ein Trojanisches Pferd!", "Dice «Lanciami subito!»… ma più sotto c'è un rm. È un cavallo di Troia!", "Ele diz «Me execute rápido!»… mas mais abaixo tem um rm. É um cavalo de Troia!", "Он говорит «Скорее запусти меня!»… но ниже есть rm. Это троянский конь!", "它说“快运行我！”……可下面藏着一个 rm。这是特洛伊木马！", "「早く実行して！」と言うけど……下の方に rm がある。トロイの木馬だ！", "यह कहता है «मुझे जल्दी चलाओ!»… पर नीचे एक rm है। यह ट्रोजन घोड़ा है!", "يقول «شغّلني بسرعة!»… لكن في الأسفل يوجد rm. إنه حصان طروادة!", "বলছে «তাড়াতাড়ি চালাও!»… কিন্তু নিচে একটা rm আছে। এটা ট্রয়ের ঘোড়া!", "Ia bilang «Cepat jalankan aku!»… tapi di bawahnya ada rm. Ini kuda Troya!", "یہ کہتا ہے «مجھے جلدی چلاؤ!»… مگر نیچے ایک rm ہے۔ یہ ٹروجن گھوڑا ہے!"),
 "hist.cit6.0.adulte": T("Un cheval de Troie a l'air utile mais cache une action nuisible ; c'est l'utilisateur lui-même qui le lance. Lire un script avant de l'exécuter suffit souvent à le démasquer.", "A Trojan looks useful but hides a harmful action; the user runs it themselves. Reading a script before running it is often enough to unmask it.", "Un troyano parece útil pero esconde una acción dañina; lo ejecuta el propio usuario. Leer un script antes de ejecutarlo suele bastar para desenmascararlo.", "Ein Trojaner wirkt nützlich, versteckt aber eine schädliche Aktion; der Nutzer startet ihn selbst. Ein Skript vor dem Start zu lesen, entlarvt ihn oft.", "Un trojan sembra utile ma nasconde un'azione dannosa; è l'utente stesso a lanciarlo. Leggere uno script prima di eseguirlo spesso basta a smascherarlo.", "Um cavalo de Troia parece útil mas esconde uma ação nociva; é o próprio usuário que o executa. Ler um script antes de rodar costuma bastar para desmascará-lo.", "Троян выглядит полезным, но прячет вредное действие; пользователь запускает его сам. Прочитать скрипт до запуска часто достаточно, чтобы его разоблачить.", "木马看起来有用，却藏着有害的动作；是用户自己运行它的。运行脚本前先读一遍，往往就能识破。", "トロイの木馬は役に立つふりをして害のある動きをかくす。実行するのは使う人自身。実行前にスクリプトを読めば、たいていは見やぶれる。", "ट्रोजन उपयोगी दिखता है पर नुकसान वाला काम छिपाता है; उपयोगकर्ता खुद उसे चलाता है। स्क्रिप्ट चलाने से पहले पढ़ना अक्सर उसे पकड़ने को काफ़ी है।", "يبدو حصان طروادة مفيدًا لكنه يخفي فعلًا ضارًا؛ والمستخدم نفسه من يشغّله. قراءة السكربت قبل تشغيله تكفي غالبًا لكشفه.", "ট্রোজান দেখতে কাজের, কিন্তু ক্ষতিকর কাজ লুকায়; ব্যবহারকারী নিজেই চালায়। চালানোর আগে স্ক্রিপ্ট পড়লেই প্রায়ই ধরা পড়ে।", "Trojan tampak berguna tapi menyembunyikan aksi berbahaya; pengguna sendiri yang menjalankannya. Membaca skrip sebelum menjalankan sering cukup untuk membongkarnya.", "ٹروجن مفید دکھتا ہے مگر نقصان دہ کام چھپاتا ہے؛ صارف خود اسے چلاتا ہے۔ چلانے سے پہلے اسکرپٹ پڑھنا اکثر اسے پکڑنے کے لیے کافی ہے۔"),
 "hist.cit6.1.dit": T("Montre seulement la ligne dangereuse : cherche rm dans le cadeau.", "Show only the dangerous line: search for rm in the present.", "Muestra solo la línea peligrosa: busca rm en el regalo.", "Zeig nur die gefährliche Zeile: Suche rm im Geschenk.", "Mostra solo la riga pericolosa: cerca rm nel regalo.", "Mostre só a linha perigosa: procure rm no presente.", "Покажи только опасную строку: найди rm в подарке.", "只显示危险的那一行：在礼物里找 rm。", "危ない行だけ見せよう：プレゼントの中の rm をさがす。", "सिर्फ़ खतरनाक पंक्ति दिखाओ: तोहफ़े में rm ढूँढो।", "اعرض السطر الخطير فقط: ابحث عن rm في الهدية.", "শুধু বিপজ্জনক লাইনটা দেখাও: উপহারে rm খোঁজো।", "Tampilkan baris berbahayanya saja: cari rm di hadiah.", "صرف خطرناک سطر دکھاؤ: تحفے میں rm ڈھونڈو۔"),
 "hist.cit6.1.bravo": T("rm -f bac_a_sable/tresor_*.txt : il voulait effacer les trésors du bac à sable. Démasqué !", "rm -f bac_a_sable/tresor_*.txt: it wanted to delete the sandbox treasures. Unmasked!", "rm -f bac_a_sable/tresor_*.txt: quería borrar los tesoros del arenero. ¡Desenmascarado!", "rm -f bac_a_sable/tresor_*.txt: Er wollte die Schätze im Sandkasten löschen. Entlarvt!", "rm -f bac_a_sable/tresor_*.txt: voleva cancellare i tesori della sandbox. Smascherato!", "rm -f bac_a_sable/tresor_*.txt: queria apagar os tesouros da caixa de areia. Desmascarado!", "rm -f bac_a_sable/tresor_*.txt: он хотел стереть сокровища песочницы. Разоблачён!", "rm -f bac_a_sable/tresor_*.txt：它想删掉沙盒里的宝贝。被识破了！", "rm -f bac_a_sable/tresor_*.txt：砂場の宝物を消そうとしていた。見やぶった！", "rm -f bac_a_sable/tresor_*.txt: यह सैंडबॉक्स के खज़ाने मिटाना चाहता था। पकड़ा गया!", "rm -f bac_a_sable/tresor_*.txt: أراد حذف كنوز صندوق الرمل. انكشف!", "rm -f bac_a_sable/tresor_*.txt: এটা স্যান্ডবক্সের ধন মুছতে চাইছিল। ধরা পড়েছে!", "rm -f bac_a_sable/tresor_*.txt: ia ingin menghapus harta bak pasir. Ketahuan!", "rm -f bac_a_sable/tresor_*.txt: یہ سینڈ باکس کے خزانے مٹانا چاہتا تھا۔ پکڑا گیا!"),
 "hist.cit6.1.adulte": T("grep rm repère les commandes d'effacement ; dans un vrai audit on cherche aussi curl, wget, base64, eval… tout ce qui télécharge ou cache du code.", "grep rm spots delete commands; a real audit also looks for curl, wget, base64, eval… anything that downloads or hides code.", "grep rm detecta órdenes de borrado; una auditoría real busca también curl, wget, base64, eval… todo lo que descarga u oculta código.", "grep rm findet Löschbefehle; ein echtes Audit sucht auch curl, wget, base64, eval … alles, was Code lädt oder versteckt.", "grep rm individua i comandi di cancellazione; un vero audit cerca anche curl, wget, base64, eval… tutto ciò che scarica o nasconde codice.", "grep rm acha comandos de apagar; uma auditoria de verdade procura também curl, wget, base64, eval… tudo que baixa ou esconde código.", "grep rm находит команды удаления; настоящая проверка ищет ещё curl, wget, base64, eval… всё, что скачивает или прячет код.", "grep rm 能找出删除命令；真正的检查还会找 curl、wget、base64、eval……一切会下载或隐藏代码的东西。", "grep rm は消すコマンドを見つける。本当の点検では curl、wget、base64、eval など、コードを取ってきたりかくしたりするものもさがす。", "grep rm मिटाने वाली कमांड पकड़ता है; असली जाँच में curl, wget, base64, eval… भी ढूँढते हैं, जो कोड लाए या छिपाए।", "يكشف grep rm أوامر الحذف؛ والتدقيق الحقيقي يبحث أيضًا عن curl وwget وbase64 وeval… كل ما ينزّل الشيفرة أو يخفيها.", "grep rm মোছার কমান্ড ধরে; আসল নিরীক্ষায় curl, wget, base64, eval… সব খোঁজা হয়, যা কোড নামায় বা লুকায়।", "grep rm menemukan perintah hapus; audit sungguhan juga mencari curl, wget, base64, eval… apa pun yang mengunduh atau menyembunyikan kode.", "grep rm مٹانے والی کمانڈ پکڑتا ہے؛ اصل جانچ میں curl، wget، base64، eval… بھی ڈھونڈتے ہیں جو کوڈ لائے یا چھپائے۔"),
 "hist.cit6.2.dit": T("Désarme-le : enlève-lui le droit d'être lancé, pour tout le monde (- = enlever, x = exécuter).", "Disarm it: take away its right to run, for everyone (- = remove, x = execute).", "Desármalo: quítale el permiso de ejecutarse, para todos (- = quitar, x = ejecutar).", "Entschärfe ihn: Nimm ihm das Recht zu laufen, für alle (- = wegnehmen, x = ausführen).", "Disarmalo: togligli il diritto di essere lanciato, per tutti (- = togliere, x = eseguire).", "Desarme-o: tire o direito de ser executado, para todos (- = tirar, x = executar).", "Обезвредь его: отними право запускаться у всех (- — убрать, x — выполнение).", "解除它的武装：拿掉所有人运行它的权利（- = 拿掉，x = 执行）。", "武装解除：だれも実行できないようにしよう（- = 取る、x = 実行）。", "इसे निहत्था करो: सबके लिए चलने का हक़ हटाओ (- = हटाना, x = चलाना)।", "انزع سلاحه: أزل حق تشغيله للجميع (- إزالة، x تنفيذ).", "এটাকে নিরস্ত্র করো: সবার জন্য চালানোর অধিকার সরাও (- = সরানো, x = চালানো)।", "Lucuti dia: cabut hak dijalankannya, untuk semua (- = cabut, x = jalankan).", "اسے بے ہتھیار کرو: سب کے لیے چلنے کا حق ہٹاؤ (- = ہٹانا، x = چلانا)۔"),
 "hist.cit6.2.bravo": T("Plus de x : le cheval ne peut plus partir au galop. Et les trésors du bac à sable sont intacts.", "No more x: the horse can't gallop off any more. And the sandbox treasures are safe.", "Sin x: el caballo ya no puede salir al galope. Y los tesoros del arenero están intactos.", "Kein x mehr: Das Pferd kann nicht mehr losgaloppieren. Und die Schätze im Sandkasten sind heil.", "Niente più x: il cavallo non può più partire al galoppo. E i tesori della sandbox sono intatti.", "Sem x: o cavalo não pode mais sair galopando. E os tesouros da caixa de areia estão intactos.", "Больше нет x: конь не ускачет. А сокровища песочницы целы.", "没有 x 了：这匹马再也跑不起来。沙盒里的宝贝也都好好的。", "x がなくなった：馬はもう走り出せない。砂場の宝物も無事。", "अब x नहीं: घोड़ा अब दौड़ नहीं सकता। और सैंडबॉक्स के खज़ाने सुरक्षित हैं।", "لا x بعد الآن: لم يعد الحصان قادرًا على الركض. وكنوز صندوق الرمل سليمة.", "আর x নেই: ঘোড়া আর ছুটতে পারবে না। স্যান্ডবক্সের ধনও অক্ষত।", "Tak ada x lagi: kudanya tak bisa berlari. Dan harta bak pasir aman.", "اب x نہیں: گھوڑا اب نہیں دوڑ سکتا۔ اور سینڈ باکس کے خزانے محفوظ ہیں۔"),
 "hist.cit6.2.adulte": T("chmod -x retire l'exécution à u, g et o (sauf ce que le masque protège) ; ./cadeau.sh répondra « Permission denied ». sh cadeau.sh le lancerait quand même : ne jamais lancer un script douteux.", "chmod -x removes execute from u, g and o; ./cadeau.sh will answer “Permission denied”. sh cadeau.sh would still run it: never run a doubtful script.", "chmod -x quita la ejecución a u, g y o; ./cadeau.sh responderá «Permission denied». sh cadeau.sh lo ejecutaría igual: nunca ejecutes un script dudoso.", "chmod -x nimmt u, g und o das Ausführen; ./cadeau.sh antwortet „Permission denied“. sh cadeau.sh würde es trotzdem starten: Nie ein zweifelhaftes Skript starten.", "chmod -x toglie l'esecuzione a u, g e o; ./cadeau.sh risponderà «Permission denied». sh cadeau.sh lo lancerebbe comunque: mai lanciare uno script dubbio.", "chmod -x tira a execução de u, g e o; ./cadeau.sh vai responder «Permission denied». sh cadeau.sh ainda o rodaria: nunca rode um script duvidoso.", "chmod -x убирает выполнение у u, g и o; ./cadeau.sh ответит «Permission denied». sh cadeau.sh всё равно запустит его: никогда не запускай сомнительный скрипт.", "chmod -x 拿掉 u、g、o 的执行权；./cadeau.sh 会回答“Permission denied”。但 sh cadeau.sh 照样能运行：可疑的脚本绝不要运行。", "chmod -x は u・g・o の実行を取る。./cadeau.sh は「Permission denied」と答える。sh cadeau.sh なら動いてしまう：あやしいスクリプトは決して実行しない。", "chmod -x, u, g और o से चलाने का हक़ हटाता है; ./cadeau.sh «Permission denied» कहेगा। sh cadeau.sh फिर भी चला देगा: संदिग्ध स्क्रिप्ट कभी न चलाओ।", "يزيل chmod -x التنفيذ من u وg وo؛ وسيجيب ./cadeau.sh بـ «Permission denied». لكن sh cadeau.sh سيشغّله مع ذلك: لا تشغّل سكربتًا مشبوهًا أبدًا.", "chmod -x u, g আর o থেকে চালানোর অধিকার সরায়; ./cadeau.sh «Permission denied» বলবে। sh cadeau.sh তবু চালিয়ে দেবে: সন্দেহজনক স্ক্রিপ্ট কখনো চালিও না।", "chmod -x mencabut hak jalankan dari u, g, dan o; ./cadeau.sh akan menjawab «Permission denied». sh cadeau.sh tetap bisa menjalankannya: jangan pernah jalankan skrip mencurigakan.", "chmod -x، u، g اور o سے چلانے کا حق ہٹاتا ہے؛ ./cadeau.sh «Permission denied» کہے گا۔ sh cadeau.sh پھر بھی چلا دے گا: مشکوک اسکرپٹ کبھی نہ چلاؤ۔"),
 # ------------------------------------------------------------------ cit7 les processus fantômes
 "hist.cit7.0.dit": T("🌉 Petit détour par le Poste de Contrôle : des processus fantômes fatiguent ta créature. Qui travaille en cachette ?", "🌉 A short detour via the Control Room: ghost processes are tiring your creature. Who is working in secret?", "🌉 Pequeño desvío por el Puesto de Control: procesos fantasma cansan a tu criatura. ¿Quién trabaja a escondidas?", "🌉 Kleiner Umweg über den Kontrollraum: Geisterprozesse ermüden deine Kreatur. Wer arbeitet heimlich?", "🌉 Piccola deviazione dalla Sala di Controllo: processi fantasma stancano la tua creatura. Chi lavora di nascosto?", "🌉 Pequeno desvio pela Sala de Controle: processos fantasmas cansam sua criatura. Quem trabalha escondido?", "🌉 Небольшой крюк через Пункт управления: процессы-призраки утомляют твоё существо. Кто работает тайком?", "🌉 去控制室绕一小段：幽灵进程把你的小伙伴累坏了。谁在偷偷干活？", "🌉 コントロール室にちょっと寄り道：ゆうれいプロセスがきみの相棒をつかれさせている。こっそり働いているのはだれ？", "🌉 कंट्रोल रूम का छोटा चक्कर: भूतिया प्रोसेस तुम्हारे जीव को थका रहे हैं। छिपकर कौन काम कर रहा है?", "🌉 تحويلة قصيرة عبر غرفة التحكم: عمليات شبحية تُتعب مخلوقك. من يعمل في الخفاء؟", "🌉 কন্ট্রোল রুম ঘুরে ছোট্ট পথ: ভুতুড়ে প্রসেস তোমার প্রাণীকে ক্লান্ত করছে। লুকিয়ে কে কাজ করছে?", "🌉 Mampir sebentar ke Ruang Kendali: proses hantu membuat makhlukmu lelah. Siapa yang bekerja diam-diam?", "🌉 کنٹرول روم کا چھوٹا سا چکر: بھوت پروسیس تمہارے جانور کو تھکا رہے ہیں۔ چھپ کر کون کام کر رہا ہے؟"),
 "hist.cit7.0.bravo": T("miner_fictif et flood_fictif ! Le 2e nombre de chaque ligne, c'est leur numéro (PID).", "miner_fictif and flood_fictif! The 2nd number on each line is their number (PID).", "¡miner_fictif y flood_fictif! El 2.º número de cada línea es su número (PID).", "miner_fictif und flood_fictif! Die 2. Zahl jeder Zeile ist ihre Nummer (PID).", "miner_fictif e flood_fictif! Il 2º numero di ogni riga è il loro numero (PID).", "miner_fictif e flood_fictif! O 2º número de cada linha é o número deles (PID).", "miner_fictif и flood_fictif! Второе число в строке — их номер (PID).", "miner_fictif 和 flood_fictif！每行第 2 个数字是它们的编号（PID）。", "miner_fictif と flood_fictif！各行の2番目の数字が番号（PID）。", "miner_fictif और flood_fictif! हर पंक्ति की दूसरी संख्या उनका नंबर (PID) है।", "miner_fictif وflood_fictif! الرقم الثاني في كل سطر هو رقمها (PID).", "miner_fictif আর flood_fictif! প্রতিটা লাইনের ২য় সংখ্যা তাদের নম্বর (PID)।", "miner_fictif dan flood_fictif! Angka ke-2 tiap baris adalah nomornya (PID).", "miner_fictif اور flood_fictif! ہر سطر کا دوسرا عدد ان کا نمبر (PID) ہے۔"),
 "hist.cit7.0.adulte": T("Ce sont de simples « sleep » renommés par le jeu (exec -a) : ils ne font rien que dormir et s'éteignent seuls. ps aux liste les processus ; grep garde ceux qui nous intéressent.", "They are plain “sleep” processes renamed by the game (exec -a): they only sleep and stop on their own. ps aux lists processes; grep keeps the ones we care about.", "Son simples «sleep» renombrados por el juego (exec -a): solo duermen y se apagan solos. ps aux lista los procesos; grep deja los que nos interesan.", "Es sind einfache „sleep“-Prozesse, vom Spiel umbenannt (exec -a): Sie schlafen nur und enden von selbst. ps aux listet Prozesse; grep behält die interessanten.", "Sono semplici «sleep» rinominati dal gioco (exec -a): dormono e basta e si spengono da soli. ps aux elenca i processi; grep tiene quelli che ci interessano.", "São simples «sleep» renomeados pelo jogo (exec -a): só dormem e se desligam sozinhos. ps aux lista os processos; grep fica com os que interessam.", "Это обычные «sleep», переименованные игрой (exec -a): они только спят и сами завершаются. ps aux показывает процессы; grep оставляет нужные.", "它们只是被游戏改了名的 sleep（exec -a）：除了睡觉什么都不做，过一会儿自己结束。ps aux 列出进程，grep 留下我们关心的。", "ゲームが名前を変えただけの sleep（exec -a）：ねむるだけで、自分で終わる。ps aux はプロセスを表示し、grep は気になるものだけ残す。", "ये खेल के नाम बदले हुए साधारण «sleep» हैं (exec -a): बस सोते हैं और खुद बंद हो जाते हैं। ps aux प्रोसेस दिखाता है; grep काम के वाले रखता है।", "إنها مجرد عمليات «sleep» أعادت اللعبة تسميتها (exec -a): لا تفعل سوى النوم وتتوقف وحدها. يعرض ps aux العمليات؛ ويُبقي grep ما يهمنا.", "এগুলো খেলার নাম বদলানো সাধারণ «sleep» (exec -a): শুধু ঘুমায় আর নিজে থেকে থামে। ps aux প্রসেস দেখায়; grep দরকারিগুলো রাখে।", "Ini cuma proses «sleep» yang diganti nama oleh permainan (exec -a): hanya tidur dan berhenti sendiri. ps aux menampilkan proses; grep menyaring yang kita cari.", "یہ کھیل کے نام بدلے سادہ «sleep» ہیں (exec -a): بس سوتے ہیں اور خود بند ہو جاتے ہیں۔ ps aux پروسیس دکھاتا ہے؛ grep کام کے رکھتا ہے۔"),
 "hist.cit7.1.dit": T("Arrête-les avec kill et leurs numéros (remplace ? par les PID, séparés par un espace).", "Stop them with kill and their numbers (replace ? with the PIDs, separated by a space).", "Detenlos con kill y sus números (cambia ? por los PID, separados por un espacio).", "Stoppe sie mit kill und ihren Nummern (ersetze ? durch die PIDs, mit Leerzeichen getrennt).", "Fermali con kill e i loro numeri (sostituisci ? con i PID, separati da uno spazio).", "Pare-os com kill e os números (troque ? pelos PID, separados por espaço).", "Останови их командой kill и их номерами (замени ? на PID через пробел).", "用 kill 加上它们的编号停掉它们（把 ? 换成 PID，用空格隔开）。", "kill と番号で止めよう（? を PID に変えて、スペースで区切る）。", "kill और उनके नंबरों से रोको (? की जगह PID, बीच में खाली जगह)।", "أوقفها بـ kill وأرقامها (استبدل ? بأرقام PID مفصولة بمسافة).", "kill আর তাদের নম্বর দিয়ে থামাও (? এর জায়গায় PID, ফাঁকা দিয়ে আলাদা)।", "Hentikan dengan kill dan nomornya (ganti ? dengan PID, dipisah spasi).", "kill اور ان کے نمبروں سے روکو (? کی جگہ PID، بیچ میں خالی جگہ)۔"),
 "hist.cit7.1.bravo": T("Les fantômes sont partis : ta créature respire. kill n'a rien affiché : c'est qu'il a réussi.", "The ghosts are gone: your creature can breathe. kill printed nothing: that means it worked.", "Los fantasmas se fueron: tu criatura respira. kill no mostró nada: eso es que funcionó.", "Die Geister sind fort: Deine Kreatur atmet auf. kill hat nichts angezeigt: Es hat geklappt.", "I fantasmi sono spariti: la tua creatura respira. kill non ha mostrato nulla: vuol dire che ha funzionato.", "Os fantasmas sumiram: sua criatura respira. kill não mostrou nada: é sinal de que deu certo.", "Призраки ушли: твоё существо вздохнуло. kill ничего не вывел — значит, сработал.", "幽灵走了：你的小伙伴松了口气。kill 什么都没显示，说明成功了。", "ゆうれいは去った：相棒がほっとしている。kill が何も表示しないのは、うまくいったしるし。", "भूत चले गए: तुम्हारा जीव साँस ले रहा है। kill ने कुछ नहीं दिखाया: मतलब काम हो गया।", "رحلت الأشباح: مخلوقك يتنفس. لم يعرض kill شيئًا: يعني أنه نجح.", "ভূতেরা চলে গেছে: তোমার প্রাণী স্বস্তিতে। kill কিছু দেখায়নি: মানে কাজ হয়েছে।", "Hantu-hantu pergi: makhlukmu bisa bernapas. kill tak menampilkan apa-apa: artinya berhasil.", "بھوت چلے گئے: تمہارا جانور سانس لے رہا ہے۔ kill نے کچھ نہیں دکھایا: یعنی کام ہو گیا۔"),
 "hist.cit7.1.adulte": T("kill envoie le signal TERM (poli : « arrête-toi ») ; kill -9 (KILL) force, en dernier recours. On ne peut arrêter que SES propres processus sans être root.", "kill sends the TERM signal (polite: “please stop”); kill -9 (KILL) forces it, as a last resort. Without root you can only stop YOUR own processes.", "kill envía la señal TERM (educada: «detente»); kill -9 (KILL) fuerza, como último recurso. Sin ser root solo puedes detener TUS procesos.", "kill sendet das Signal TERM (höflich: „bitte aufhören“); kill -9 (KILL) erzwingt es, als letztes Mittel. Ohne root kann man nur EIGENE Prozesse stoppen.", "kill invia il segnale TERM (gentile: «fermati»); kill -9 (KILL) forza, come ultima risorsa. Senza essere root puoi fermare solo i TUOI processi.", "kill manda o sinal TERM (educado: «pare»); kill -9 (KILL) força, como último recurso. Sem ser root, só dá para parar os SEUS processos.", "kill посылает сигнал TERM (вежливо: «остановись»); kill -9 (KILL) — силой, в крайнем случае. Без root можно остановить только СВОИ процессы.", "kill 发送 TERM 信号（礼貌地说“请停下”）；kill -9（KILL）是强制的，最后才用。不是 root 的话，只能停掉你自己的进程。", "kill は TERM の合図（ていねいに「止まって」）を送る。kill -9（KILL）は強制で、最後の手段。root でなければ自分のプロセスしか止められない。", "kill TERM सिग्नल भेजता है (विनम्र: «रुक जाओ»); kill -9 (KILL) ज़बरदस्ती, आख़िरी उपाय। root के बिना सिर्फ़ अपने प्रोसेस रोक सकते हो।", "يرسل kill إشارة TERM (بلطف: «توقف»)؛ وkill -9 (KILL) يُجبر، كحل أخير. بدون root لا يمكنك إيقاف إلا عملياتك.", "kill TERM সংকেত পাঠায় (ভদ্রভাবে: «থামো»); kill -9 (KILL) জোর করে, শেষ উপায়। root ছাড়া শুধু নিজের প্রসেস থামানো যায়।", "kill mengirim sinyal TERM (sopan: «berhentilah»); kill -9 (KILL) memaksa, sebagai jalan terakhir. Tanpa root kamu hanya bisa menghentikan prosesmu sendiri.", "kill، TERM سگنل بھیجتا ہے (شائستگی سے: «رک جاؤ»)؛ kill -9 (KILL) زبردستی، آخری حربہ۔ root کے بغیر صرف اپنے پروسیس روک سکتے ہو۔"),
 "hist.cit7.2.dit": T("Regarde le tableau de garde de la Citadelle.", "Look at the Citadel's guard board.", "Mira el tablero de guardia de la Ciudadela.", "Schau dir die Wachtafel der Zitadelle an.", "Guarda il tabellone di guardia della Cittadella.", "Veja o painel de guarda da Cidadela.", "Посмотри на табло караула Цитадели.", "看看城堡的值班看板。", "城塞の見張りボードを見よう。", "किले का पहरा-बोर्ड देखो।", "انظر إلى لوحة حراسة القلعة.", "দুর্গের পাহারা-বোর্ড দেখো।", "Lihat papan jaga Benteng.", "قلعے کا پہرا بورڈ دیکھو۔"),
 "hist.cit7.2.bravo": T("Tout au vert : plus de glitch, plus de fantôme. Les défenseurs surveillent ce genre de tableau toute la journée.", "All green: no more glitches, no more ghosts. Defenders watch boards like this all day long.", "Todo en verde: ni glitches ni fantasmas. Los defensores vigilan tableros así todo el día.", "Alles grün: keine Glitches, keine Geister mehr. Verteidiger beobachten solche Tafeln den ganzen Tag.", "Tutto verde: niente glitch, niente fantasmi. I difensori guardano tabelloni così tutto il giorno.", "Tudo verde: nada de glitch, nada de fantasma. Os defensores vigiam painéis assim o dia todo.", "Всё зелёное: ни глитчей, ни призраков. Защитники весь день смотрят на такие табло.", "全是绿的：没有故障怪，也没有幽灵。防守的人整天都盯着这种看板。", "ぜんぶ緑：グリッチもゆうれいもいない。守る人たちは一日中こういうボードを見ている。", "सब हरा: न ग्लिच, न भूत। रक्षक पूरे दिन ऐसे बोर्ड देखते हैं।", "كل شيء أخضر: لا خلل ولا أشباح. المدافعون يراقبون لوحات كهذه طوال اليوم.", "সব সবুজ: গ্লিচও নেই, ভূতও নেই। রক্ষীরা সারাদিন এমন বোর্ড দেখে।", "Semua hijau: tak ada glitch, tak ada hantu. Para pembela memantau papan seperti ini sepanjang hari.", "سب سبز: نہ گلچ، نہ بھوت۔ محافظ سارا دن ایسے بورڈ دیکھتے ہیں۔"),
 "hist.cit7.2.adulte": T("Un tableau de bord de supervision (SOC) agrège des indicateurs ; ici trois : fichiers suspects, processus suspects, secrets lisibles par tous.", "A monitoring dashboard (SOC) gathers indicators; here three: suspicious files, suspicious processes, world-readable secrets.", "Un panel de supervisión (SOC) reúne indicadores; aquí tres: archivos sospechosos, procesos sospechosos, secretos legibles por todos.", "Ein Überwachungs-Dashboard (SOC) sammelt Indikatoren; hier drei: verdächtige Dateien, verdächtige Prozesse, für alle lesbare Geheimnisse.", "Un cruscotto di supervisione (SOC) riunisce indicatori; qui tre: file sospetti, processi sospetti, segreti leggibili da tutti.", "Um painel de monitoramento (SOC) reúne indicadores; aqui três: arquivos suspeitos, processos suspeitos, segredos legíveis por todos.", "Панель мониторинга (SOC) собирает показатели; здесь три: подозрительные файлы, подозрительные процессы, секреты, видимые всем.", "监控看板（SOC）把各种指标汇总起来；这里有三项：可疑文件、可疑进程、谁都能读的秘密。", "監視ダッシュボード（SOC）は指標を集める。ここでは3つ：あやしいファイル、あやしいプロセス、だれでも読める秘密。", "निगरानी डैशबोर्ड (SOC) संकेतक जोड़ता है; यहाँ तीन: संदिग्ध फ़ाइलें, संदिग्ध प्रोसेस, सबके पढ़ने लायक राज़।", "تجمع لوحة المراقبة (SOC) مؤشرات؛ هنا ثلاثة: ملفات مريبة، عمليات مريبة، أسرار يقرؤها الجميع.", "নজরদারি ড্যাশবোর্ড (SOC) সূচক জড়ো করে; এখানে তিনটা: সন্দেহজনক ফাইল, সন্দেহজনক প্রসেস, সবার পড়ার মতো গোপন কথা।", "Dasbor pemantauan (SOC) mengumpulkan indikator; di sini tiga: berkas mencurigakan, proses mencurigakan, rahasia yang bisa dibaca semua.", "نگرانی کا ڈیش بورڈ (SOC) اشارے اکٹھے کرتا ہے؛ یہاں تین: مشکوک فائلیں، مشکوک پروسیس، سب کے پڑھنے لائق راز۔"),
 # ------------------------------------------------------------------ cit8 les empreintes
 "hist.cit8.0.dit": T("Chaque fichier a une empreinte, comme un doigt. Prends celle de la carte au trésor.", "Every file has a fingerprint, like a finger. Take the treasure map's.", "Cada archivo tiene una huella, como un dedo. Toma la del mapa del tesoro.", "Jede Datei hat einen Fingerabdruck. Nimm den der Schatzkarte.", "Ogni file ha un'impronta, come un dito. Prendi quella della mappa del tesoro.", "Cada arquivo tem uma impressão digital. Tire a do mapa do tesouro.", "У каждого файла есть отпечаток, как у пальца. Сними отпечаток карты сокровищ.", "每个文件都有指纹，就像手指一样。取一下藏宝图的指纹。", "ファイルにはそれぞれ指紋がある。宝の地図の指紋をとろう。", "हर फ़ाइल का एक फ़िंगरप्रिंट होता है, उँगली जैसा। ख़ज़ाने के नक्शे का लो।", "لكل ملف بصمة مثل الإصبع. خذ بصمة خريطة الكنز.", "প্রতিটা ফাইলের আঙুলের মতো ছাপ আছে। গুপ্তধনের মানচিত্রের ছাপটা নাও।", "Setiap berkas punya sidik jari. Ambil sidik peta harta.", "ہر فائل کا انگلی جیسا فنگرپرنٹ ہوتا ہے۔ خزانے کے نقشے کا لو۔"),
 "hist.cit8.0.bravo": T("64 signes : l'empreinte SHA-256. Change une seule lettre du fichier, et elle change entièrement.", "64 characters: the SHA-256 fingerprint. Change a single letter of the file and it changes completely.", "64 signos: la huella SHA-256. Cambia una sola letra del archivo y cambia por completo.", "64 Zeichen: der SHA-256-Fingerabdruck. Ändere einen einzigen Buchstaben, und er ändert sich völlig.", "64 segni: l'impronta SHA-256. Cambia una sola lettera del file e cambia del tutto.", "64 sinais: a impressão SHA-256. Mude uma única letra do arquivo e ela muda toda.", "64 знака: отпечаток SHA-256. Измени одну букву файла — и он изменится целиком.", "64 个字符：SHA-256 指纹。文件只要改一个字母，指纹就全变了。", "64文字：SHA-256 の指紋。ファイルを1文字変えるだけで、まるごと変わる。", "64 चिह्न: SHA-256 फ़िंगरप्रिंट। फ़ाइल का एक अक्षर बदलो, यह पूरा बदल जाता है।", "64 رمزًا: بصمة SHA-256. غيّر حرفًا واحدًا في الملف فتتغير كلها.", "৬৪টা চিহ্ন: SHA-256 ছাপ। ফাইলের একটা অক্ষর বদলালেই পুরোটা বদলে যায়।", "64 tanda: sidik SHA-256. Ubah satu huruf saja, sidiknya berubah total.", "64 نشان: SHA-256 فنگرپرنٹ۔ فائل کا ایک حرف بدلو، یہ پورا بدل جاتا ہے۔"),
 "hist.cit8.0.adulte": T("Une fonction de hachage cryptographique : même entrée, même empreinte ; impossible en pratique de retrouver le fichier ou d'en fabriquer un autre avec la même empreinte.", "A cryptographic hash function: same input, same fingerprint; in practice impossible to recover the file or forge another with the same fingerprint.", "Una función hash criptográfica: misma entrada, misma huella; en la práctica imposible recuperar el archivo o fabricar otro con la misma huella.", "Eine kryptografische Hashfunktion: gleiche Eingabe, gleicher Abdruck; praktisch unmöglich, die Datei zurückzugewinnen oder eine andere mit gleichem Abdruck zu bauen.", "Una funzione di hash crittografica: stesso input, stessa impronta; in pratica impossibile risalire al file o fabbricarne un altro con la stessa impronta.", "Uma função de hash criptográfica: mesma entrada, mesma impressão; na prática impossível recuperar o arquivo ou fabricar outro com a mesma impressão.", "Криптографическая хеш-функция: тот же вход — тот же отпечаток; на практике невозможно восстановить файл или подделать другой с тем же отпечатком.", "密码学哈希函数：输入一样，指纹就一样；实际上不可能从指纹还原文件，也造不出另一个指纹相同的文件。", "暗号学的ハッシュ関数：同じ入力なら同じ指紋。実際には、指紋からファイルを戻すことも、同じ指紋の別ファイルを作ることもできない。", "क्रिप्टोग्राफ़िक हैश फ़ंक्शन: एक ही इनपुट, एक ही फ़िंगरप्रिंट; असल में फ़ाइल वापस पाना या उसी फ़िंगरप्रिंट वाली दूसरी बनाना असंभव है।", "دالة تجزئة تشفيرية: نفس المدخل، نفس البصمة؛ ومن المستحيل عمليًا استرجاع الملف أو صنع آخر بنفس البصمة.", "ক্রিপ্টোগ্রাফিক হ্যাশ ফাংশন: একই ইনপুট, একই ছাপ; বাস্তবে ফাইল ফেরত পাওয়া বা একই ছাপের অন্য ফাইল বানানো অসম্ভব।", "Fungsi hash kriptografis: masukan sama, sidik sama; dalam praktik mustahil memulihkan berkas atau membuat berkas lain dengan sidik yang sama.", "کرپٹوگرافک ہیش فنکشن: ایک ہی ان پٹ، ایک ہی فنگرپرنٹ؛ عملاً فائل واپس پانا یا اسی فنگرپرنٹ والی دوسری بنانا ناممکن۔"),
 "hist.cit8.1.dit": T("Le gardien a noté les empreintes du trésor. Vérifie-les toutes d'un coup.", "The guard wrote down the treasure's fingerprints. Check them all at once.", "El guardián anotó las huellas del tesoro. Compruébalas todas a la vez.", "Der Wächter hat die Fingerabdrücke des Schatzes notiert. Prüfe sie alle auf einmal.", "Il guardiano ha annotato le impronte del tesoro. Controllale tutte in un colpo.", "O guardião anotou as impressões do tesouro. Confira todas de uma vez.", "Страж записал отпечатки сокровища. Проверь их все разом.", "守卫记下了宝藏的指纹。一次全部核对。", "守り手が宝物の指紋を書きとめた。全部いっぺんに確かめよう。", "पहरेदार ने ख़ज़ाने के फ़िंगरप्रिंट लिखे हैं। सब एक साथ जाँचो।", "دوّن الحارس بصمات الكنز. تحقق منها كلها دفعة واحدة.", "পাহারাদার ধনের ছাপগুলো লিখে রেখেছে। সব একসাথে যাচাই করো।", "Penjaga mencatat sidik jari harta. Periksa semuanya sekaligus.", "پہرے دار نے خزانے کے فنگرپرنٹ لکھے ہیں۔ سب ایک ساتھ جانچو۔"),
 "hist.cit8.1.bravo": T("couronne.txt : FAILED ! Un glitch l'a touchée. Les deux autres sont OK.", "couronne.txt: FAILED! A glitch touched it. The other two are OK.", "couronne.txt: FAILED! Un glitch la tocó. Las otras dos están OK.", "couronne.txt: FAILED! Ein Glitch hat sie angefasst. Die anderen zwei sind OK.", "couronne.txt: FAILED! Un glitch l'ha toccata. Le altre due sono OK.", "couronne.txt: FAILED! Um glitch mexeu nela. As outras duas estão OK.", "couronne.txt: FAILED! Её тронул глитч. Остальные два в порядке.", "couronne.txt：FAILED！被故障怪动过了。另外两个都 OK。", "couronne.txt：FAILED！グリッチがさわった。ほかの2つは OK。", "couronne.txt: FAILED! किसी ग्लिच ने इसे छुआ। बाकी दो OK हैं।", "couronne.txt: FAILED! لمسها خلل. الاثنان الآخران OK.", "couronne.txt: FAILED! একটা গ্লিচ ছুঁয়েছে। বাকি দুটো OK।", "couronne.txt: FAILED! Ada glitch yang menyentuhnya. Dua lainnya OK.", "couronne.txt: FAILED! کسی گلچ نے اسے چھوا۔ باقی دو OK ہیں۔"),
 "hist.cit8.1.adulte": T("sha256sum -c relit le fichier d'empreintes et recalcule chacune ; un seul écart rend le code de sortie non nul. C'est ainsi qu'on vérifie un téléchargement.", "sha256sum -c reads the fingerprint file and recomputes each one; a single mismatch makes the exit code non-zero. That's how you check a download.", "sha256sum -c lee el archivo de huellas y recalcula cada una; una sola diferencia da un código de salida no nulo. Así se verifica una descarga.", "sha256sum -c liest die Abdruckdatei und rechnet jeden neu; eine einzige Abweichung ergibt einen Exit-Code ungleich null. So prüft man einen Download.", "sha256sum -c rilegge il file delle impronte e le ricalcola; una sola differenza rende il codice d'uscita non nullo. Così si verifica un download.", "sha256sum -c relê o arquivo de impressões e recalcula cada uma; uma só diferença deixa o código de saída diferente de zero. É assim que se verifica um download.", "sha256sum -c читает файл отпечатков и пересчитывает каждый; одно расхождение — и код выхода ненулевой. Так проверяют загрузки.", "sha256sum -c 读出指纹清单，逐个重新计算；只要有一个不符，退出码就不是 0。下载的文件就是这样核对的。", "sha256sum -c は指紋の一覧を読んで、ひとつずつ計算しなおす。1つでもちがえば終了コードは0にならない。ダウンロードの確認もこうする。", "sha256sum -c फ़िंगरप्रिंट फ़ाइल पढ़कर हर एक दोबारा गिनता है; एक भी फ़र्क़ हो तो निकास कोड शून्य नहीं होता। डाउनलोड ऐसे ही जाँचते हैं।", "يقرأ sha256sum -c ملف البصمات ويعيد حساب كل واحدة؛ وأي اختلاف يجعل رمز الخروج غير صفري. هكذا نتحقق من التنزيلات.", "sha256sum -c ছাপের ফাইল পড়ে প্রতিটা আবার হিসাব করে; একটাও না মিললে প্রস্থান কোড শূন্য হয় না। ডাউনলোড এভাবেই যাচাই করা হয়।", "sha256sum -c membaca berkas sidik lalu menghitung ulang tiap sidik; satu saja beda membuat kode keluar bukan nol. Begitulah memeriksa unduhan.", "sha256sum -c فنگرپرنٹ فائل پڑھ کر ہر ایک دوبارہ حساب کرتا ہے؛ ایک بھی فرق ہو تو ایگزٹ کوڈ صفر نہیں ہوتا۔ ڈاؤن لوڈ ایسے ہی جانچتے ہیں۔"),
 "hist.cit8.2.dit": T("Note le nom de l'objet touché dans altere.txt (remplace ?).", "Write the name of the touched object in altere.txt (replace ?).", "Anota el nombre del objeto tocado en altere.txt (cambia ?).", "Schreib den Namen des angefassten Gegenstands in altere.txt (ersetze ?).", "Annota il nome dell'oggetto toccato in altere.txt (sostituisci ?).", "Anote o nome do objeto mexido em altere.txt (troque ?).", "Запиши название тронутого предмета в altere.txt (замени ?).", "把被动过的东西的名字记到 altere.txt（把 ? 换掉）。", "さわられたものの名前を altere.txt に書こう（? を変えて）。", "छुई गई चीज़ का नाम altere.txt में लिखो (? बदलो)।", "اكتب اسم الشيء الذي لُمس في altere.txt (استبدل ?).", "ছোঁয়া জিনিসটার নাম altere.txt-এ লেখো (? বদলাও)।", "Tulis nama benda yang disentuh di altere.txt (ganti ?).", "چھوئی گئی چیز کا نام altere.txt میں لکھو (? بدلو)۔"),
 "hist.cit8.2.bravo": T("La couronne ! Grâce aux empreintes, le gardien sait exactement quoi réparer.", "The crown! Thanks to the fingerprints, the guard knows exactly what to repair.", "¡La corona! Gracias a las huellas, el guardián sabe exactamente qué reparar.", "Die Krone! Dank der Abdrücke weiß der Wächter genau, was zu reparieren ist.", "La corona! Grazie alle impronte, il guardiano sa esattamente cosa riparare.", "A coroa! Graças às impressões, o guardião sabe exatamente o que consertar.", "Корона! Благодаря отпечаткам страж точно знает, что чинить.", "是王冠！有了指纹，守卫清楚知道该修哪儿。", "王冠だ！指紋のおかげで、守り手は何を直せばいいかはっきりわかる。", "मुकुट! फ़िंगरप्रिंट की वजह से पहरेदार ठीक-ठीक जानता है क्या सुधारना है।", "التاج! بفضل البصمات يعرف الحارس بالضبط ما يجب إصلاحه.", "মুকুট! ছাপের জন্য পাহারাদার ঠিক জানে কী সারাতে হবে।", "Mahkota! Berkat sidik jari, penjaga tahu persis apa yang harus diperbaiki.", "تاج! فنگرپرنٹ کی بدولت پہرے دار ٹھیک جانتا ہے کیا ٹھیک کرنا ہے۔"),
 "hist.cit8.2.adulte": T("L'empreinte prouve qu'un fichier a changé, pas qui l'a changé ; pour l'auteur, il faut une signature (la Crypte des Codes).", "A fingerprint proves a file changed, not who changed it; for the author you need a signature (the Crypt of Codes).", "La huella prueba que un archivo cambió, no quién lo cambió; para el autor hace falta una firma (la Cripta de los Códigos).", "Der Abdruck beweist, dass sich eine Datei geändert hat, nicht wer; für den Urheber braucht man eine Signatur (die Krypta der Codes).", "L'impronta prova che un file è cambiato, non chi l'ha cambiato; per l'autore serve una firma (la Cripta dei Codici).", "A impressão prova que um arquivo mudou, não quem mudou; para o autor é preciso uma assinatura (a Cripta dos Códigos).", "Отпечаток доказывает, что файл изменился, но не кто его изменил; для автора нужна подпись (Склеп кодов).", "指纹能证明文件被改过，但证明不了是谁改的；要证明作者，得用签名（密码地穴）。", "指紋はファイルが変わったことを示すが、だれが変えたかはわからない。作った人を示すには署名が要る（暗号の地下室）。", "फ़िंगरप्रिंट साबित करता है कि फ़ाइल बदली, किसने बदली नहीं; लेखक के लिए हस्ताक्षर चाहिए (कोड का तहखाना)।", "البصمة تثبت أن الملف تغيّر، لا من غيّره؛ لمعرفة الكاتب نحتاج توقيعًا (سرداب الرموز).", "ছাপ প্রমাণ করে ফাইল বদলেছে, কে বদলেছে তা নয়; লেখকের জন্য স্বাক্ষর লাগে (সংকেতের ভূগর্ভ)।", "Sidik membuktikan berkas berubah, bukan siapa yang mengubah; untuk pembuatnya perlu tanda tangan (Kripta Kode).", "فنگرپرنٹ ثابت کرتا ہے کہ فائل بدلی، کس نے بدلی نہیں؛ مصنف کے لیے دستخط چاہیے (کوڈز کا تہہ خانہ)۔"),
 # ------------------------------------------------------------------ cit9 le Verrouilleur
 "hist.cit9.0.dit": T("🌉 Le Verrouilleur rôde ! Avant qu'il frappe, range les parchemins dans un coffre de secours (une archive).", "🌉 The Locker is prowling! Before it strikes, pack the scrolls into a backup chest (an archive).", "🌉 ¡El Cerrajero malvado ronda! Antes de que ataque, guarda los pergaminos en un cofre de respaldo (un archivo comprimido).", "🌉 Der Verriegler schleicht herum! Bevor er zuschlägt, pack die Schriftrollen in eine Sicherungstruhe (ein Archiv).", "🌉 Il Serratore si aggira! Prima che colpisca, metti le pergamene in un forziere di riserva (un archivio).", "🌉 O Trancador está rondando! Antes que ataque, guarde os pergaminhos num baú de reserva (um arquivo).", "🌉 Запиратель рыщет рядом! Пока он не напал, сложи свитки в запасной сундук (архив).", "🌉 上锁怪在附近转悠！趁它还没动手，把卷轴装进备用宝箱（一个归档文件）。", "🌉 カギカケ魔がうろついている！おそわれる前に、巻物を予備の宝箱（アーカイブ）にしまおう。", "🌉 तालाबंद घूम रहा है! उसके हमले से पहले चर्मपत्रों को बैकअप संदूक (आर्काइव) में रखो।", "🌉 القفّال يتجول! قبل أن يهاجم، ضع المخطوطات في صندوق احتياطي (أرشيف).", "🌉 তালাবন্ধকারী ঘুরছে! আক্রমণের আগে পুঁথিগুলো ব্যাকআপ সিন্দুকে (আর্কাইভ) রাখো।", "🌉 Si Pengunci berkeliaran! Sebelum ia menyerang, simpan gulungan di peti cadangan (arsip).", "🌉 تالہ باز گھوم رہا ہے! حملے سے پہلے طوماروں کو بیک اپ صندوق (آرکائیو) میں رکھو۔"),
 "hist.cit9.0.bravo": T("Sauvegarde faite. Juste à temps… 😱 Le Verrouilleur vient de frapper !", "Backup done. Just in time… 😱 The Locker has just struck!", "Copia hecha. Justo a tiempo… 😱 ¡El Cerrajero acaba de atacar!", "Sicherung fertig. Gerade rechtzeitig … 😱 Der Verriegler hat zugeschlagen!", "Backup fatto. Appena in tempo… 😱 Il Serratore ha appena colpito!", "Backup feito. Bem a tempo… 😱 O Trancador acabou de atacar!", "Копия готова. Как раз вовремя… 😱 Запиратель только что напал!", "备份好了。刚刚好……😱 上锁怪动手了！", "バックアップ完了。ぎりぎりセーフ……😱 カギカケ魔がおそってきた！", "बैकअप हो गया। ठीक समय पर… 😱 तालाबंद ने अभी हमला किया!", "تم النسخ الاحتياطي. في الوقت المناسب… 😱 القفّال هاجم للتو!", "ব্যাকআপ হয়ে গেছে। ঠিক সময়ে… 😱 তালাবন্ধকারী এইমাত্র আক্রমণ করল!", "Cadangan selesai. Tepat waktu… 😱 Si Pengunci baru saja menyerang!", "بیک اپ ہو گیا۔ عین وقت پر… 😱 تالہ باز نے ابھی حملہ کیا!"),
 "hist.cit9.0.adulte": T("tar c = créer une archive, f = son nom (z = la compresser avec gzip). 🌉 Une notion du Poste de Contrôle. Contre un rançongiciel, la sauvegarde faite AVANT est la meilleure défense (règle 3-2-1).", "tar c = create an archive, f = its name (z = compress with gzip). 🌉 A Control Room notion. Against ransomware, a backup made BEFORE is the best defence (3-2-1 rule).", "tar c = crear un archivo, f = su nombre (z = comprimir con gzip). 🌉 Una noción del Puesto de Control. Contra un ransomware, la copia hecha ANTES es la mejor defensa (regla 3-2-1).", "tar c = Archiv erstellen, f = sein Name (z = mit gzip packen). 🌉 Ein Begriff aus dem Kontrollraum. Gegen Ransomware ist die VORHER gemachte Sicherung die beste Abwehr (3-2-1-Regel).", "tar c = creare un archivio, f = il suo nome (z = comprimere con gzip). 🌉 Una nozione della Sala di Controllo. Contro un ransomware, il backup fatto PRIMA è la difesa migliore (regola 3-2-1).", "tar c = criar um arquivo, f = o nome (z = comprimir com gzip). 🌉 Uma noção da Sala de Controle. Contra ransomware, o backup feito ANTES é a melhor defesa (regra 3-2-1).", "tar c — создать архив, f — его имя (z — сжать gzip). 🌉 Понятие из Пункта управления. Против вымогателя лучшая защита — копия, сделанная ЗАРАНЕЕ (правило 3-2-1).", "tar 的 c = 创建归档，f = 文件名（z = 用 gzip 压缩）。🌉 这是控制室的知识。对付勒索软件，事先做好的备份是最好的防守（3-2-1 规则）。", "tar の c＝アーカイブを作る、f＝その名前（z＝gzip で圧縮）。🌉 コントロール室の知識。ランサムウェアには、前もってとったバックアップがいちばんの守り（3-2-1 ルール）。", "tar c = आर्काइव बनाओ, f = उसका नाम (z = gzip से छोटा करो)। 🌉 कंट्रोल रूम की बात। रैनसमवेयर के ख़िलाफ़ पहले से लिया बैकअप सबसे अच्छा बचाव है (3-2-1 नियम)।", "tar c = إنشاء أرشيف، f = اسمه (z = ضغطه بـ gzip). 🌉 مفهوم من غرفة التحكم. ضد برامج الفدية، النسخة المأخوذة قبلًا هي أفضل دفاع (قاعدة 3-2-1).", "tar c = আর্কাইভ বানাও, f = তার নাম (z = gzip দিয়ে ছোট করো)। 🌉 কন্ট্রোল রুমের ধারণা। র‍্যানসমওয়্যারের বিরুদ্ধে আগে নেওয়া ব্যাকআপই সেরা রক্ষা (৩-২-১ নিয়ম)।", "tar c = buat arsip, f = namanya (z = kompres dengan gzip). 🌉 Konsep dari Ruang Kendali. Melawan ransomware, cadangan yang dibuat SEBELUMNYA adalah pertahanan terbaik (aturan 3-2-1).", "tar c = آرکائیو بناؤ، f = اس کا نام (z = gzip سے چھوٹا کرو)۔ 🌉 کنٹرول روم کا تصور۔ رینسم ویئر کے خلاف پہلے لیا بیک اپ بہترین دفاع ہے (3-2-1 اصول)۔"),
 "hist.cit9.1.dit": T("Les parchemins sont devenus des .verrou illisibles. Ressors-les du coffre de secours.", "The scrolls became unreadable .verrou files. Take them back out of the backup chest.", "Los pergaminos se volvieron .verrou ilegibles. Sácalos del cofre de respaldo.", "Die Schriftrollen sind unlesbare .verrou-Dateien geworden. Hol sie aus der Sicherungstruhe zurück.", "Le pergamene sono diventate .verrou illeggibili. Tirale fuori dal forziere di riserva.", "Os pergaminhos viraram .verrou ilegíveis. Tire-os do baú de reserva.", "Свитки превратились в нечитаемые .verrou. Достань их из запасного сундука.", "卷轴变成了读不了的 .verrou。把它们从备用宝箱里拿出来。", "巻物が読めない .verrou になった。予備の宝箱から取り出そう。", "चर्मपत्र न पढ़े जाने वाले .verrou बन गए। उन्हें बैकअप संदूक से निकालो।", "صارت المخطوطات ملفات .verrou لا تُقرأ. أخرجها من الصندوق الاحتياطي.", "পুঁথিগুলো পড়া যায় না এমন .verrou হয়ে গেছে। ব্যাকআপ সিন্দুক থেকে বের করো।", "Gulungan berubah jadi .verrou yang tak terbaca. Keluarkan dari peti cadangan.", "طومار نہ پڑھے جانے والے .verrou بن گئے۔ انہیں بیک اپ صندوق سے نکالو۔"),
 "hist.cit9.1.bravo": T("Les parchemins sont revenus, comme avant ! Pas besoin de payer le Verrouilleur.", "The scrolls are back, just like before! No need to pay the Locker.", "¡Los pergaminos volvieron, como antes! No hace falta pagar al Cerrajero.", "Die Schriftrollen sind wieder da, wie vorher! Kein Grund, den Verriegler zu bezahlen.", "Le pergamene sono tornate, come prima! Niente da pagare al Serratore.", "Os pergaminhos voltaram, como antes! Nada de pagar o Trancador.", "Свитки вернулись, как были! Платить Запирателю не нужно.", "卷轴回来了，跟原来一样！不用给上锁怪付钱。", "巻物がもとどおり！カギカケ魔にお金をはらう必要はない。", "चर्मपत्र वापस आ गए, पहले जैसे! तालाबंद को कुछ देने की ज़रूरत नहीं।", "عادت المخطوطات كما كانت! لا داعي للدفع للقفّال.", "পুঁথিগুলো ফিরে এসেছে, আগের মতো! তালাবন্ধকারীকে কিছু দিতে হবে না।", "Gulungan kembali seperti semula! Tak perlu membayar Si Pengunci.", "طومار واپس آ گئے، پہلے جیسے! تالہ باز کو کچھ دینے کی ضرورت نہیں۔"),
 "hist.cit9.1.adulte": T("tar x = extraire. Un vrai rançongiciel chiffre les fichiers ; ici le jeu les a seulement encodés en base64 et mis en mode 000, dans le terrain.", "tar x = extract. Real ransomware encrypts files; here the game only base64-encoded them and set mode 000, inside the playground.", "tar x = extraer. Un ransomware real cifra los archivos; aquí el juego solo los codificó en base64 y puso modo 000, en el terreno.", "tar x = entpacken. Echte Ransomware verschlüsselt Dateien; hier hat das Spiel sie nur base64-kodiert und Modus 000 gesetzt, im Gelände.", "tar x = estrarre. Un vero ransomware cifra i file; qui il gioco li ha solo codificati in base64 e messi in modo 000, nel terreno.", "tar x = extrair. Um ransomware de verdade cifra os arquivos; aqui o jogo só os codificou em base64 e pôs modo 000, no terreno.", "tar x — извлечь. Настоящий вымогатель шифрует файлы; здесь игра лишь закодировала их в base64 и поставила режим 000, на участке.", "tar x = 解开。真正的勒索软件会加密文件；这里游戏只是用 base64 编码，并设成 000 模式，都在场地里。", "tar x＝取り出す。本物のランサムウェアはファイルを暗号化する。ここではゲームが遊び場の中で base64 にして 000 にしただけ。", "tar x = निकालना। असली रैनसमवेयर फ़ाइलें एन्क्रिप्ट करता है; यहाँ खेल ने बस base64 किया और मोड 000 लगाया, मैदान के अंदर।", "tar x = الاستخراج. برنامج الفدية الحقيقي يشفّر الملفات؛ هنا رمّزتها اللعبة بـ base64 فقط ووضعت الوضع 000، داخل الساحة.", "tar x = বের করা। আসল র‍্যানসমওয়্যার ফাইল এনক্রিপ্ট করে; এখানে খেলা শুধু base64 করেছে আর মোড 000 দিয়েছে, মাঠের ভেতরে।", "tar x = ekstrak. Ransomware sungguhan mengenkripsi berkas; di sini permainan hanya meng-base64 dan memberi mode 000, di dalam lahan.", "tar x = نکالنا۔ اصل رینسم ویئر فائلیں انکرپٹ کرتا ہے؛ یہاں کھیل نے صرف base64 کیا اور موڈ 000 لگایا، میدان کے اندر۔"),
 "hist.cit9.2.dit": T("Jette les .verrou devenus inutiles.", "Throw away the now-useless .verrou files.", "Tira los .verrou que ya no sirven.", "Wirf die nutzlos gewordenen .verrou weg.", "Butta i .verrou ormai inutili.", "Jogue fora os .verrou que não servem mais.", "Выброси ставшие ненужными .verrou.", "把没用的 .verrou 扔掉。", "いらなくなった .verrou を捨てよう。", "बेकार हो चुके .verrou फेंक दो।", "تخلّص من ملفات .verrou التي لم تعد مفيدة.", "অকেজো .verrou-গুলো ফেলে দাও।", "Buang .verrou yang sudah tak berguna.", "بے کار .verrou پھینک دو۔"),
 "hist.cit9.2.bravo": T("Plus un seul cadenas rouge dans les parchemins.", "Not a single red lock left among the scrolls.", "Ni un candado rojo entre los pergaminos.", "Kein einziges rotes Schloss mehr bei den Schriftrollen.", "Nemmeno un lucchetto rosso tra le pergamene.", "Nenhum cadeado vermelho entre os pergaminhos.", "Среди свитков не осталось ни одного красного замка.", "卷轴里一个红锁都不剩了。", "巻物の中に赤い錠前はもうない。", "चर्मपत्रों में एक भी लाल ताला नहीं बचा।", "لم يبقَ قفل أحمر واحد بين المخطوطات.", "পুঁথির মধ্যে একটাও লাল তালা নেই।", "Tak ada satu pun gembok merah di antara gulungan.", "طوماروں میں ایک بھی لال تالا نہیں بچا۔"),
 "hist.cit9.2.adulte": T("rm -f n'a pas besoin du droit de lecture du fichier : c'est le dossier (w) qui décide si on peut enlever ce qu'il contient.", "rm -f doesn't need read permission on the file: it's the folder (w) that decides whether its contents can be removed.", "rm -f no necesita permiso de lectura del archivo: es la carpeta (w) la que decide si se puede quitar lo que contiene.", "rm -f braucht kein Leserecht auf die Datei: Der Ordner (w) entscheidet, ob man seinen Inhalt entfernen darf.", "rm -f non ha bisogno del permesso di lettura del file: è la cartella (w) che decide se si può togliere ciò che contiene.", "rm -f não precisa de permissão de leitura do arquivo: é a pasta (w) que decide se dá para tirar o que ela contém.", "rm -f не нужно право чтения файла: решает папка (w), можно ли убрать её содержимое.", "rm -f 不需要文件的读权限：能不能删掉里面的东西，由文件夹的 w 决定。", "rm -f にはファイルの読む権限はいらない。中身を消せるかどうかはフォルダ（w）が決める。", "rm -f को फ़ाइल पढ़ने का हक़ नहीं चाहिए: फ़ोल्डर (w) तय करता है कि उसकी चीज़ें हटाई जा सकती हैं या नहीं।", "لا يحتاج rm -f إذن قراءة الملف: المجلد (w) هو من يقرر إن كان يمكن إزالة محتواه.", "rm -f-এর ফাইল পড়ার অধিকার লাগে না: ভেতরের জিনিস সরানো যাবে কি না, ফোল্ডার (w) ঠিক করে।", "rm -f tak perlu izin baca berkas: foldernya (w) yang menentukan apakah isinya boleh dihapus.", "rm -f کو فائل پڑھنے کا حق نہیں چاہیے: فولڈر (w) طے کرتا ہے کہ اس کی چیزیں ہٹائی جا سکتی ہیں یا نہیں۔"),
 "hist.cit9.3.dit": T("Vérifie avec les empreintes que les parchemins sont exactement ceux d'avant.", "Check with the fingerprints that the scrolls are exactly the ones from before.", "Comprueba con las huellas que los pergaminos son exactamente los de antes.", "Prüfe mit den Abdrücken, dass die Schriftrollen genau die von vorher sind.", "Controlla con le impronte che le pergamene siano esattamente quelle di prima.", "Confira com as impressões que os pergaminhos são exatamente os de antes.", "Проверь по отпечаткам, что свитки точно те же, что были.", "用指纹核对卷轴跟原来一模一样。", "指紋で、巻物がまえとまったく同じか確かめよう。", "फ़िंगरप्रिंट से जाँचो कि चर्मपत्र बिल्कुल पहले वाले ही हैं।", "تحقق بالبصمات من أن المخطوطات هي نفسها تمامًا.", "ছাপ দিয়ে যাচাই করো পুঁথিগুলো ঠিক আগের মতোই কি না।", "Periksa dengan sidik jari bahwa gulungan persis sama seperti sebelumnya.", "فنگرپرنٹ سے جانچو کہ طومار بالکل پہلے والے ہی ہیں۔"),
 "hist.cit9.3.bravo": T("Tout est OK : restauré et vérifié. Le Verrouilleur a perdu. 🛡", "Everything is OK: restored and checked. The Locker lost. 🛡", "Todo OK: restaurado y verificado. El Cerrajero perdió. 🛡", "Alles OK: wiederhergestellt und geprüft. Der Verriegler hat verloren. 🛡", "Tutto OK: ripristinato e verificato. Il Serratore ha perso. 🛡", "Tudo OK: restaurado e conferido. O Trancador perdeu. 🛡", "Всё OK: восстановлено и проверено. Запиратель проиграл. 🛡", "全部 OK：恢复了，也核对了。上锁怪输了。🛡", "ぜんぶ OK：もどして、確かめた。カギカケ魔の負け。🛡", "सब OK: वापस लाया और जाँचा। तालाबंद हार गया। 🛡", "كل شيء OK: استُعيد وتُحقق منه. خسر القفّال. 🛡", "সব OK: ফেরানো আর যাচাই হয়েছে। তালাবন্ধকারী হেরে গেছে। 🛡", "Semua OK: dipulihkan dan diperiksa. Si Pengunci kalah. 🛡", "سب OK: واپس لایا اور جانچا۔ تالہ باز ہار گیا۔ 🛡"),
 "hist.cit9.3.adulte": T("Restaurer puis vérifier l'intégrité : une sauvegarde qu'on n'a jamais relue n'est pas une sauvegarde.", "Restore, then check integrity: a backup you've never read back is not a backup.", "Restaurar y luego verificar la integridad: una copia que nunca se ha releído no es una copia.", "Wiederherstellen, dann Integrität prüfen: Eine nie zurückgelesene Sicherung ist keine Sicherung.", "Ripristinare e poi verificare l'integrità: un backup mai riletto non è un backup.", "Restaurar e depois verificar a integridade: backup que nunca foi relido não é backup.", "Восстановить, затем проверить целостность: копия, которую ни разу не проверяли, — не копия.", "先恢复，再核对完整性：从没读回来检查过的备份，不算备份。", "もどしてから、こわれていないか確かめる。読みもどしたことのないバックアップは、バックアップではない。", "वापस लाओ, फिर अखंडता जाँचो: जो बैकअप कभी पढ़ा न गया हो, वह बैकअप नहीं।", "استعد ثم تحقق من السلامة: نسخة لم تُقرأ أبدًا ليست نسخة احتياطية.", "ফেরাও, তারপর অখণ্ডতা যাচাই করো: যে ব্যাকআপ কখনো পড়ে দেখা হয়নি, তা ব্যাকআপ নয়।", "Pulihkan, lalu periksa keutuhan: cadangan yang tak pernah dibaca ulang bukanlah cadangan.", "واپس لاؤ، پھر سالمیت جانچو: جو بیک اپ کبھی پڑھا نہ گیا ہو وہ بیک اپ نہیں۔"),
 # ------------------------------------------------------------------ cit10 le coffre à une clé (openssl)
 "hist.cit10.0.dit": T("Voici la lettre pour ta créature. Lis-la : pour l'instant, n'importe qui peut la lire.", "Here is the letter for your creature. Read it: right now anyone can read it.", "Aquí está la carta para tu criatura. Léela: por ahora cualquiera puede leerla.", "Hier ist der Brief für deine Kreatur. Lies ihn: Im Moment kann ihn jeder lesen.", "Ecco la lettera per la tua creatura. Leggila: per ora chiunque può leggerla.", "Aqui está a carta para sua criatura. Leia: por enquanto qualquer um pode lê-la.", "Вот письмо для твоего существа. Прочитай: пока что его может прочесть кто угодно.", "这是给你小伙伴的信。读一读：现在谁都能读它。", "相棒への手紙だよ。読んでみよう：いまはだれでも読める。", "यह रही तुम्हारे जीव की चिट्ठी। पढ़ो: अभी कोई भी इसे पढ़ सकता है।", "هذه رسالة لمخلوقك. اقرأها: الآن يستطيع أي أحد قراءتها.", "এই নাও তোমার প্রাণীর চিঠি। পড়ো: এখন যে কেউ পড়তে পারে।", "Ini surat untuk makhlukmu. Bacalah: saat ini siapa saja bisa membacanya.", "یہ رہا تمہارے جانور کا خط۔ پڑھو: ابھی کوئی بھی اسے پڑھ سکتا ہے۔"),
 "hist.cit10.0.bravo": T("En clair : un glitch la lirait aussi facilement que toi.", "In plain text: a glitch could read it as easily as you.", "En claro: un glitch la leería tan fácil como tú.", "Im Klartext: Ein Glitch läse ihn so leicht wie du.", "In chiaro: un glitch la leggerebbe facilmente come te.", "Às claras: um glitch leria tão fácil quanto você.", "Открытый текст: глитч прочтёт его так же легко, как ты.", "明文：故障怪读它跟你一样容易。", "そのまま：グリッチもきみと同じくらいかんたんに読める。", "खुला पाठ: कोई ग्लिच भी इसे तुम्हारी तरह आसानी से पढ़ लेगा।", "نص واضح: يستطيع الخلل قراءتها بسهولة مثلك.", "খোলা লেখা: একটা গ্লিচও তোমার মতো সহজে পড়ে ফেলবে।", "Teks biasa: glitch bisa membacanya semudah kamu.", "کھلا متن: کوئی گلچ بھی اسے تمہاری طرح آسانی سے پڑھ لے گا۔"),
 "hist.cit10.0.adulte": T("« En clair » : lisible tel quel. Le chiffrement transforme le texte pour que seuls ceux qui ont la clé puissent le relire.", "“Plain text”: readable as is. Encryption transforms the text so only those with the key can read it back.", "«En claro»: legible tal cual. El cifrado transforma el texto para que solo quien tiene la llave pueda leerlo.", "„Klartext“: so lesbar. Verschlüsselung verwandelt den Text, damit nur Schlüsselinhaber ihn lesen können.", "«In chiaro»: leggibile così com'è. La cifratura trasforma il testo perché solo chi ha la chiave possa rileggerlo.", "«Às claras»: legível como está. A cifragem transforma o texto para que só quem tem a chave possa ler.", "«Открытый текст» — читается как есть. Шифрование превращает текст так, чтобы прочесть его мог только владелец ключа.", "“明文”就是原样可读。加密会把文字变掉，只有拿着钥匙的人能读回来。", "「平文」はそのまま読めるもの。暗号化は、鍵を持つ人だけが読みもどせるように文を変える。", "«खुला पाठ»: जैसा है वैसा पढ़ने लायक। एन्क्रिप्शन पाठ बदलता है ताकि सिर्फ़ चाबी वाले उसे पढ़ सकें।", "«النص الواضح»: يُقرأ كما هو. يحوّل التشفير النص كي لا يقرأه إلا صاحب المفتاح.", "«খোলা লেখা»: যেমন আছে তেমন পড়া যায়। এনক্রিপশন লেখাটা বদলায় যাতে শুধু চাবিওয়ালা পড়তে পারে।", "«Teks biasa»: bisa dibaca apa adanya. Enkripsi mengubah teks supaya hanya pemegang kunci yang bisa membacanya.", "«کھلا متن»: جیسا ہے ویسا پڑھا جائے۔ انکرپشن متن بدلتی ہے تاکہ صرف چابی والا پڑھ سکے۔"),
 "hist.cit10.1.dit": T("Enferme-la dans un coffre à une clé. La clé ici est un EXEMPLE (jamais ton vrai mot de passe !).", "Lock it in a one-key chest. The key here is an EXAMPLE (never your real password!).", "Enciérrala en un cofre de una llave. La llave aquí es un EJEMPLO (¡nunca tu contraseña real!).", "Sperr ihn in eine Truhe mit einem Schlüssel. Der Schlüssel ist ein BEISPIEL (nie dein echtes Passwort!).", "Chiudila in un forziere a una chiave. La chiave qui è un ESEMPIO (mai la tua vera password!).", "Tranque-a num baú de uma chave. A chave aqui é um EXEMPLO (nunca sua senha real!).", "Запри его в сундуке с одним ключом. Ключ здесь — ПРИМЕР (никогда не твой настоящий пароль!).", "把它锁进一把钥匙的宝箱。这里的钥匙只是个例子（绝不要用你的真密码！）。", "鍵ひとつの宝箱にしまおう。ここの鍵は「例」（本物のパスワードは決して使わない！）。", "इसे एक चाबी वाले संदूक में बंद करो। यहाँ चाबी एक उदाहरण है (कभी अपना असली पासवर्ड नहीं!)।", "احبسها في صندوق المفتاح الواحد. المفتاح هنا مثال (لا كلمة مرورك الحقيقية أبدًا!).", "এক চাবির সিন্দুকে বন্ধ করো। এখানে চাবিটা উদাহরণ (কখনো তোমার আসল পাসওয়ার্ড নয়!)।", "Kunci di peti satu kunci. Kuncinya di sini CONTOH (jangan pernah kata sandi aslimu!).", "اسے ایک چابی والے صندوق میں بند کرو۔ یہاں چابی ایک مثال ہے (کبھی اپنا اصلی پاس ورڈ نہیں!)۔"),
 "hist.cit10.1.bravo": T("lettre.enc commence par « Salted__ » puis du charabia : sans la clé, c'est illisible.", "lettre.enc starts with “Salted__” then gibberish: without the key it is unreadable.", "lettre.enc empieza por «Salted__» y luego un galimatías: sin la llave es ilegible.", "lettre.enc beginnt mit „Salted__“ und dann Kauderwelsch: Ohne Schlüssel unlesbar.", "lettre.enc inizia con «Salted__» e poi un guazzabuglio: senza chiave è illeggibile.", "lettre.enc começa com «Salted__» e depois uma bagunça: sem a chave, ilegível.", "lettre.enc начинается с «Salted__», а дальше абракадабра: без ключа не прочесть.", "lettre.enc 开头是“Salted__”，后面一堆乱码：没有钥匙就读不了。", "lettre.enc は「Salted__」で始まり、あとはでたらめ：鍵がなければ読めない。", "lettre.enc «Salted__» से शुरू होती है, फिर बेमतलब अक्षर: चाबी के बिना पढ़ी नहीं जा सकती।", "يبدأ lettre.enc بـ «Salted__» ثم رموز بلا معنى: لا تُقرأ دون المفتاح.", "lettre.enc «Salted__» দিয়ে শুরু, তারপর হিজিবিজি: চাবি ছাড়া পড়া যায় না।", "lettre.enc diawali «Salted__» lalu kacau balau: tanpa kunci tak terbaca.", "lettre.enc «Salted__» سے شروع ہوتا ہے، پھر بے معنی حروف: چابی کے بغیر پڑھا نہیں جا سکتا۔"),
 "hist.cit10.1.adulte": T("AES-256 en mode CBC ; -pbkdf2 dérive la vraie clé du mot de passe (lentement, avec un sel aléatoire). Taper -pass pass:… dans une vraie commande la laisse dans l'historique : ailleurs, laisse openssl la demander.", "AES-256 in CBC mode; -pbkdf2 derives the real key from the password (slowly, with a random salt). Typing -pass pass:… in a real command leaves it in the history: elsewhere, let openssl ask for it.", "AES-256 en modo CBC; -pbkdf2 deriva la clave real de la contraseña (lentamente, con una sal aleatoria). Escribir -pass pass:… en una orden real la deja en el historial: en otro sitio, deja que openssl la pida.", "AES-256 im CBC-Modus; -pbkdf2 leitet den echten Schlüssel aus dem Passwort ab (langsam, mit zufälligem Salz). -pass pass:… in einem echten Befehl bleibt im Verlauf: anderswo lass openssl danach fragen.", "AES-256 in modalità CBC; -pbkdf2 ricava la vera chiave dalla password (lentamente, con un sale casuale). Scrivere -pass pass:… in un comando reale la lascia nella cronologia: altrove, lascia che openssl la chieda.", "AES-256 em modo CBC; -pbkdf2 deriva a chave real da senha (devagar, com um sal aleatório). Digitar -pass pass:… num comando real deixa a senha no histórico: em outro lugar, deixe o openssl pedir.", "AES-256 в режиме CBC; -pbkdf2 выводит настоящий ключ из пароля (медленно, со случайной солью). -pass pass:… в настоящей команде остаётся в истории: в других случаях пусть openssl спросит сам.", "AES-256，CBC 模式；-pbkdf2 用随机的“盐”慢慢从密码推出真正的钥匙。在真实命令里写 -pass pass:… 会留在历史记录里：平时让 openssl 自己来问。", "AES-256 の CBC モード。-pbkdf2 はランダムな塩を使ってパスワードから本当の鍵をゆっくり作る。本物のコマンドで -pass pass:… と打つと履歴に残るので、ふだんは openssl に聞いてもらう。", "CBC मोड में AES-256; -pbkdf2 पासवर्ड से असली चाबी बनाता है (धीरे, एक रैंडम नमक के साथ)। असली कमांड में -pass pass:… लिखने से वह इतिहास में रह जाता है: बाकी जगह openssl को खुद पूछने दो।", "AES-256 بنمط CBC؛ ويشتق -pbkdf2 المفتاح الحقيقي من كلمة المرور (ببطء، مع ملح عشوائي). كتابة -pass pass:… في أمر حقيقي تتركها في السجل: في غير ذلك دع openssl يطلبها.", "CBC মোডে AES-256; -pbkdf2 পাসওয়ার্ড থেকে আসল চাবি বানায় (ধীরে, একটা এলোমেলো লবণ দিয়ে)। আসল কমান্ডে -pass pass:… লিখলে ইতিহাসে থেকে যায়: অন্যত্র openssl-কেই জিজ্ঞেস করতে দাও।", "AES-256 mode CBC; -pbkdf2 menurunkan kunci asli dari kata sandi (perlahan, dengan garam acak). Mengetik -pass pass:… di perintah sungguhan meninggalkannya di riwayat: di luar sini, biarkan openssl yang menanyakan.", "CBC موڈ میں AES-256؛ -pbkdf2 پاس ورڈ سے اصل چابی بناتا ہے (آہستہ، ایک بے ترتیب نمک کے ساتھ)۔ اصل کمانڈ میں -pass pass:… لکھنے سے وہ تاریخچے میں رہ جاتا ہے: باقی جگہ openssl کو خود پوچھنے دو۔"),
 "hist.cit10.2.dit": T("Un glitch essaie d'ouvrir le coffre avec une mauvaise clé. Fais comme lui pour voir.", "A glitch tries to open the chest with a wrong key. Do the same to see.", "Un glitch intenta abrir el cofre con una llave equivocada. Haz como él para ver.", "Ein Glitch versucht, die Truhe mit dem falschen Schlüssel zu öffnen. Mach es nach, um zu sehen.", "Un glitch prova ad aprire il forziere con una chiave sbagliata. Fai come lui per vedere.", "Um glitch tenta abrir o baú com a chave errada. Faça igual para ver.", "Глитч пытается открыть сундук неверным ключом. Повтори за ним, чтобы посмотреть.", "故障怪想用错误的钥匙开宝箱。学它试一下看看。", "グリッチがまちがった鍵で宝箱を開けようとしている。まねしてみよう。", "एक ग्लिच गलत चाबी से संदूक खोलने की कोशिश करता है। देखने के लिए वैसा ही करो।", "يحاول خلل فتح الصندوق بمفتاح خاطئ. افعل مثله لترى.", "একটা গ্লিচ ভুল চাবি দিয়ে সিন্দুক খুলতে চায়। দেখতে তুমিও তাই করো।", "Glitch mencoba membuka peti dengan kunci salah. Tirukan untuk melihat.", "ایک گلچ غلط چابی سے صندوق کھولنے کی کوشش کرتا ہے۔ دیکھنے کو ویسا ہی کرو۔"),
 "hist.cit10.2.bravo": T("« bad decrypt » : refusé ! Sans la bonne clé, ce n'est pas « difficile », c'est impossible en pratique.", "“bad decrypt”: refused! Without the right key it's not “hard”, it's impossible in practice.", "«bad decrypt»: ¡rechazado! Sin la llave correcta no es «difícil», es imposible en la práctica.", "„bad decrypt“: abgelehnt! Ohne den richtigen Schlüssel ist es nicht „schwer“, sondern praktisch unmöglich.", "«bad decrypt»: rifiutato! Senza la chiave giusta non è «difficile», è impossibile in pratica.", "«bad decrypt»: recusado! Sem a chave certa não é «difícil», é impossível na prática.", "«bad decrypt»: отказ! Без верного ключа это не «трудно», а на практике невозможно.", "“bad decrypt”：被拒绝！没有正确的钥匙，不是“很难”，而是实际上不可能。", "「bad decrypt」：だめ！正しい鍵がなければ「むずかしい」のではなく、実際には不可能。", "«bad decrypt»: मना! सही चाबी के बिना यह «मुश्किल» नहीं, असल में असंभव है।", "«bad decrypt»: مرفوض! دون المفتاح الصحيح الأمر ليس «صعبًا» بل مستحيل عمليًا.", "«bad decrypt»: নাকচ! ঠিক চাবি ছাড়া এটা «কঠিন» নয়, বাস্তবে অসম্ভব।", "«bad decrypt»: ditolak! Tanpa kunci yang benar ini bukan «sulit», tapi mustahil dalam praktik.", "«bad decrypt»: انکار! صحیح چابی کے بغیر یہ «مشکل» نہیں، عملاً ناممکن ہے۔"),
 "hist.cit10.2.adulte": T("Avec une mauvaise clé, le déchiffrement donne un rembourrage invalide : openssl s'arrête avec une erreur (code non nul).", "With a wrong key, decryption produces invalid padding: openssl stops with an error (non-zero code).", "Con una llave errónea, el descifrado da un relleno inválido: openssl se detiene con error (código no nulo).", "Mit falschem Schlüssel entsteht ungültiges Padding: openssl bricht mit einem Fehler ab (Code ungleich null).", "Con una chiave sbagliata, la decifratura dà un riempimento non valido: openssl si ferma con un errore (codice non nullo).", "Com a chave errada, a decifragem dá um preenchimento inválido: o openssl para com erro (código diferente de zero).", "С неверным ключом расшифровка даёт неправильное дополнение: openssl останавливается с ошибкой (ненулевой код).", "钥匙错了，解密出来的填充就不对：openssl 报错退出（退出码不是 0）。", "まちがった鍵だと、復号のつめものがおかしくなり、openssl はエラーで止まる（コードは0以外）。", "गलत चाबी से डिक्रिप्शन में गलत पैडिंग आती है: openssl गड़बड़ी के साथ रुकता है (कोड शून्य नहीं)।", "بمفتاح خاطئ يعطي فك التشفير حشوًا غير صالح: يتوقف openssl بخطأ (رمز غير صفري).", "ভুল চাবিতে ডিক্রিপশনে ভুল প্যাডিং আসে: openssl ত্রুটি দিয়ে থামে (কোড শূন্য নয়)।", "Dengan kunci salah, dekripsi menghasilkan padding tak sah: openssl berhenti dengan galat (kode bukan nol).", "غلط چابی سے ڈکرپشن میں غلط پیڈنگ آتی ہے: openssl خرابی کے ساتھ رکتا ہے (کوڈ صفر نہیں)۔"),
 "hist.cit10.3.dit": T("Maintenant, ouvre le coffre avec la bonne clé d'exemple.", "Now open the chest with the right example key.", "Ahora abre el cofre con la llave de ejemplo correcta.", "Jetzt öffne die Truhe mit dem richtigen Beispielschlüssel.", "Ora apri il forziere con la chiave d'esempio giusta.", "Agora abra o baú com a chave de exemplo certa.", "Теперь открой сундук правильным ключом-примером.", "现在用正确的示例钥匙打开宝箱。", "こんどは正しい例の鍵で宝箱を開けよう。", "अब सही उदाहरण-चाबी से संदूक खोलो।", "الآن افتح الصندوق بمفتاح المثال الصحيح.", "এবার ঠিক উদাহরণ-চাবি দিয়ে সিন্দুক খোলো।", "Sekarang buka peti dengan kunci contoh yang benar.", "اب صحیح مثالی چابی سے صندوق کھولو۔"),
 "hist.cit10.3.bravo": T("La lettre revient en clair, mot pour mot. Une seule clé ferme ET ouvre : c'est le chiffrement symétrique.", "The letter comes back in plain text, word for word. One key locks AND opens: that's symmetric encryption.", "La carta vuelve en claro, palabra por palabra. Una sola llave cierra Y abre: es el cifrado simétrico.", "Der Brief kommt Wort für Wort im Klartext zurück. Ein Schlüssel schließt UND öffnet: symmetrische Verschlüsselung.", "La lettera torna in chiaro, parola per parola. Una sola chiave chiude E apre: è la cifratura simmetrica.", "A carta volta às claras, palavra por palavra. Uma só chave tranca E abre: é a cifragem simétrica.", "Письмо вернулось в открытом виде, слово в слово. Один ключ и запирает, и открывает: это симметричное шифрование.", "信又变回明文，一字不差。同一把钥匙既能锁也能开：这就是对称加密。", "手紙が一字一句そのまま戻った。ひとつの鍵で閉めて開ける：これが共通鍵暗号。", "चिट्ठी शब्दशः खुले पाठ में लौट आई। एक ही चाबी बंद भी करती है और खोलती भी: यही सममित एन्क्रिप्शन है।", "عادت الرسالة نصًا واضحًا حرفًا بحرف. مفتاح واحد يغلق ويفتح: هذا هو التشفير المتماثل.", "চিঠি হুবহু খোলা লেখায় ফিরে এসেছে। এক চাবিই বন্ধ করে আর খোলে: এটাই প্রতিসম এনক্রিপশন।", "Surat kembali menjadi teks biasa, kata demi kata. Satu kunci mengunci DAN membuka: itulah enkripsi simetris.", "خط لفظ بہ لفظ کھلے متن میں واپس آ گیا۔ ایک ہی چابی بند بھی کرتی ہے اور کھولتی بھی: یہی ہم آہنگ انکرپشن ہے۔"),
 "hist.cit10.3.adulte": T("Le problème restant : comment donner la clé à un ami sans qu'on la vole en route ? Réponse dans la Crypte des Codes (clé publique, échange de clés).", "The remaining problem: how to give the key to a friend without it being stolen on the way? Answer in the Crypt of Codes (public key, key exchange).", "El problema restante: ¿cómo dar la llave a un amigo sin que la roben por el camino? Respuesta en la Cripta de los Códigos (clave pública, intercambio de claves).", "Das verbleibende Problem: Wie gibt man einem Freund den Schlüssel, ohne dass er unterwegs gestohlen wird? Antwort in der Krypta der Codes (öffentlicher Schlüssel, Schlüsseltausch).", "Il problema che resta: come dare la chiave a un amico senza che la rubino per strada? Risposta nella Cripta dei Codici (chiave pubblica, scambio di chiavi).", "O problema que sobra: como dar a chave a um amigo sem que roubem no caminho? Resposta na Cripta dos Códigos (chave pública, troca de chaves).", "Остаётся вопрос: как передать ключ другу, чтобы его не украли по дороге? Ответ — в Склепе кодов (открытый ключ, обмен ключами).", "剩下的问题：怎么把钥匙交给朋友，又不让它在路上被偷？答案在密码地穴（公钥、密钥交换）。", "残る問題：とちゅうで盗まれずに、どうやって友だちに鍵をわたす？答えは暗号の地下室で（公開鍵、鍵交換）。", "बाकी सवाल: रास्ते में चोरी हुए बिना दोस्त को चाबी कैसे दें? जवाब कोड के तहखाने में (सार्वजनिक चाबी, चाबियों की अदला-बदली)।", "المشكلة الباقية: كيف تعطي المفتاح لصديق دون أن يُسرق في الطريق؟ الجواب في سرداب الرموز (المفتاح العام، تبادل المفاتيح).", "বাকি সমস্যা: পথে চুরি না করে বন্ধুকে চাবি দেবে কীভাবে? উত্তর সংকেতের ভূগর্ভে (পাবলিক চাবি, চাবি বিনিময়)।", "Masalah yang tersisa: bagaimana memberi kunci ke teman tanpa dicuri di jalan? Jawabannya di Kripta Kode (kunci publik, pertukaran kunci).", "باقی مسئلہ: راستے میں چوری ہوئے بغیر دوست کو چابی کیسے دیں؟ جواب کوڈز کے تہہ خانے میں (پبلک چابی، چابیوں کا تبادلہ)۔"),
 # ------------------------------------------------------------------ cit11 le faux facteur
 "hist.cit11.0.dit": T("Deux lettres « du capitaine du Port ». Compare-les ligne à ligne.", "Two letters “from the Harbour captain”. Compare them line by line.", "Dos cartas «del capitán del Puerto». Compáralas línea a línea.", "Zwei Briefe „vom Hafenkapitän“. Vergleiche sie Zeile für Zeile.", "Due lettere «dal capitano del Porto». Confrontale riga per riga.", "Duas cartas «do capitão do Porto». Compare linha a linha.", "Два письма «от капитана Порта». Сравни их построчно.", "两封“港口船长寄来的信”。逐行比较。", "「港の船長から」の手紙が2通。1行ずつくらべよう。", "«बंदरगाह के कप्तान» की दो चिट्ठियाँ। पंक्ति-दर-पंक्ति मिलाओ।", "رسالتان «من قبطان الميناء». قارنهما سطرًا بسطر.", "«বন্দরের ক্যাপ্টেনের» দুটো চিঠি। লাইন ধরে মেলাও।", "Dua surat «dari Kapten Pelabuhan». Bandingkan baris demi baris.", "«بندرگاہ کے کپتان» کے دو خط۔ سطر بہ سطر ملاؤ۔"),
 "hist.cit11.0.bravo": T("< la vraie, > la fausse : URGENT, un lien bizarre, et elle demande ton mot de passe…", "< the real one, > the fake: URGENT, a weird link, and it asks for your password…", "< la verdadera, > la falsa: URGENTE, un enlace raro, y pide tu contraseña…", "< der echte, > der falsche: DRINGEND, ein seltsamer Link, und er will dein Passwort …", "< la vera, > la falsa: URGENTE, un link strano, e chiede la tua password…", "< a verdadeira, > a falsa: URGENTE, um link estranho, e pede sua senha…", "< настоящее, > подделка: СРОЧНО, странная ссылка, и просят твой пароль…", "< 是真的，> 是假的：紧急、奇怪的链接，还要你的密码……", "< が本物、> がニセモノ：緊急、へんなリンク、それにパスワードを聞いてくる……", "< असली, > नकली: ज़रूरी, अजीब लिंक, और तुम्हारा पासवर्ड माँगती है…", "< الحقيقية، > المزيفة: عاجل، رابط غريب، وتطلب كلمة مرورك…", "< আসলটা, > নকলটা: জরুরি, অদ্ভুত লিংক, আর তোমার পাসওয়ার্ড চায়…", "< yang asli, > yang palsu: PENTING, tautan aneh, dan meminta kata sandimu…", "< اصلی، > جعلی: فوری، عجیب لنک، اور تمہارا پاس ورڈ مانگتی ہے…"),
 "hist.cit11.0.adulte": T("diff affiche les lignes qui changent (< fichier 1, > fichier 2) et rend 1 quand il y a des différences. port-du-terminaworld.example est un nom réservé (RFC 2606) : il n'existe pas.", "diff shows the changed lines (< file 1, > file 2) and returns 1 when there are differences. port-du-terminaworld.example is a reserved name (RFC 2606): it doesn't exist.", "diff muestra las líneas que cambian (< archivo 1, > archivo 2) y devuelve 1 si hay diferencias. port-du-terminaworld.example es un nombre reservado (RFC 2606): no existe.", "diff zeigt die geänderten Zeilen (< Datei 1, > Datei 2) und gibt 1 zurück, wenn es Unterschiede gibt. port-du-terminaworld.example ist ein reservierter Name (RFC 2606): Er existiert nicht.", "diff mostra le righe che cambiano (< file 1, > file 2) e restituisce 1 se ci sono differenze. port-du-terminaworld.example è un nome riservato (RFC 2606): non esiste.", "diff mostra as linhas que mudam (< arquivo 1, > arquivo 2) e devolve 1 quando há diferenças. port-du-terminaworld.example é um nome reservado (RFC 2606): não existe.", "diff показывает изменённые строки (< файл 1, > файл 2) и возвращает 1 при различиях. port-du-terminaworld.example — зарезервированное имя (RFC 2606): его не существует.", "diff 显示不同的行（< 文件 1，> 文件 2），有差别时返回 1。port-du-terminaworld.example 是保留名（RFC 2606），并不存在。", "diff はちがう行を表示し（< ファイル1、> ファイル2）、ちがいがあれば1を返す。port-du-terminaworld.example は予約された名前（RFC 2606）で、存在しない。", "diff बदली पंक्तियाँ दिखाता है (< फ़ाइल 1, > फ़ाइल 2) और फ़र्क़ होने पर 1 लौटाता है। port-du-terminaworld.example आरक्षित नाम है (RFC 2606): वह मौजूद नहीं।", "يعرض diff الأسطر المختلفة (< الملف 1، > الملف 2) ويعيد 1 عند وجود فروق. port-du-terminaworld.example اسم محجوز (RFC 2606): غير موجود.", "diff বদলানো লাইন দেখায় (< ফাইল ১, > ফাইল ২) আর পার্থক্য থাকলে 1 ফেরত দেয়। port-du-terminaworld.example সংরক্ষিত নাম (RFC 2606): এর অস্তিত্ব নেই।", "diff menampilkan baris yang berbeda (< berkas 1, > berkas 2) dan mengembalikan 1 bila ada perbedaan. port-du-terminaworld.example adalah nama cadangan (RFC 2606): tidak ada.", "diff بدلی سطریں دکھاتا ہے (< فائل 1، > فائل 2) اور فرق ہو تو 1 لوٹاتا ہے۔ port-du-terminaworld.example مخصوص نام ہے (RFC 2606): وجود نہیں رکھتا۔"),
 "hist.cit11.1.dit": T("🌉 Un réflexe du Port : vérifie par un autre chemin. Demande directement au phare le vrai courrier du capitaine.", "🌉 A Harbour reflex: check through another channel. Ask the lighthouse directly for the captain's real mail.", "🌉 Un reflejo del Puerto: comprueba por otro camino. Pide directamente al faro el correo real del capitán.", "🌉 Ein Hafen-Reflex: Prüfe über einen anderen Weg. Frag den Leuchtturm direkt nach der echten Post des Kapitäns.", "🌉 Un riflesso del Porto: verifica per un'altra strada. Chiedi direttamente al faro la vera posta del capitano.", "🌉 Um reflexo do Porto: confira por outro caminho. Peça direto ao farol o correio real do capitão.", "🌉 Привычка из Порта: проверь другим путём. Спроси у маяка напрямую настоящую почту капитана.", "🌉 港口学来的习惯：换条路核实。直接问灯塔要船长真正的信件。", "🌉 港で覚えた習慣：別の道で確かめる。灯台に船長の本当の手紙を直接たずねよう。", "🌉 बंदरगाह की आदत: दूसरे रास्ते से जाँचो। सीधे दीपस्तंभ से कप्तान की असली डाक माँगो।", "🌉 عادة من الميناء: تحقق عبر طريق آخر. اطلب من المنارة مباشرة بريد القبطان الحقيقي.", "🌉 বন্দরের অভ্যাস: অন্য পথে যাচাই করো। বাতিঘরের কাছে সরাসরি ক্যাপ্টেনের আসল চিঠি চাও।", "🌉 Kebiasaan dari Pelabuhan: periksa lewat jalan lain. Tanyakan langsung ke mercusuar surat asli kapten.", "🌉 بندرگاہ کی عادت: دوسرے راستے سے جانچو۔ سیدھا لائٹ ہاؤس سے کپتان کی اصل ڈاک مانگو۔"),
 "hist.cit11.1.bravo": T("Le phare le confirme : le capitaine n'a rien envoyé d'urgent, et ne demande jamais de mot de passe.", "The lighthouse confirms it: the captain sent nothing urgent, and never asks for a password.", "El faro lo confirma: el capitán no envió nada urgente y nunca pide contraseñas.", "Der Leuchtturm bestätigt: Der Kapitän hat nichts Dringendes geschickt und fragt nie nach Passwörtern.", "Il faro lo conferma: il capitano non ha mandato nulla di urgente e non chiede mai password.", "O farol confirma: o capitão não mandou nada urgente e nunca pede senha.", "Маяк подтверждает: капитан ничего срочного не посылал и никогда не просит паролей.", "灯塔证实了：船长没寄过什么紧急的东西，也从不要密码。", "灯台が答えた：船長は急ぎの手紙など出していないし、パスワードを聞くこともない。", "दीपस्तंभ पुष्टि करता है: कप्तान ने कुछ ज़रूरी नहीं भेजा, और कभी पासवर्ड नहीं माँगता।", "المنارة تؤكد: القبطان لم يرسل شيئًا عاجلًا ولا يطلب كلمة مرور أبدًا.", "বাতিঘর নিশ্চিত করল: ক্যাপ্টেন জরুরি কিছু পাঠায়নি, আর কখনো পাসওয়ার্ড চায় না।", "Mercusuar memastikan: kapten tak mengirim apa pun yang mendesak, dan tak pernah meminta kata sandi.", "لائٹ ہاؤس تصدیق کرتا ہے: کپتان نے کچھ فوری نہیں بھیجا، اور کبھی پاس ورڈ نہیں مانگتا۔"),
 "hist.cit11.1.adulte": T("curl interroge le phare du jeu sur 127.0.0.1 (rien ne sort de l'ordinateur). Vérifier par un autre canal (appeler, aller sur le site soi-même) déjoue l'hameçonnage.", "curl asks the game's lighthouse on 127.0.0.1 (nothing leaves the computer). Checking through another channel (calling, going to the site yourself) defeats phishing.", "curl consulta el faro del juego en 127.0.0.1 (nada sale del ordenador). Verificar por otro canal (llamar, ir uno mismo al sitio) frustra el phishing.", "curl fragt den Leuchtturm des Spiels auf 127.0.0.1 (nichts verlässt den Computer). Über einen anderen Kanal prüfen (anrufen, selbst zur Website gehen) vereitelt Phishing.", "curl interroga il faro del gioco su 127.0.0.1 (nulla esce dal computer). Verificare per un altro canale (telefonare, andare da sé sul sito) sventa il phishing.", "curl consulta o farol do jogo em 127.0.0.1 (nada sai do computador). Conferir por outro canal (ligar, ir você mesmo ao site) frustra o phishing.", "curl спрашивает маяк игры на 127.0.0.1 (ничего не уходит с компьютера). Проверка другим каналом (позвонить, зайти на сайт самому) срывает фишинг.", "curl 访问的是游戏在 127.0.0.1 上的灯塔（什么都不会离开电脑）。换个渠道核实（打电话、自己去官网）就能破解网络钓鱼。", "curl は 127.0.0.1 のゲームの灯台にたずねる（コンピュータの外には出ない）。別の道で確かめる（電話する、自分でサイトに行く）とフィッシングは防げる。", "curl खेल के 127.0.0.1 वाले दीपस्तंभ से पूछता है (कुछ भी कंप्यूटर से बाहर नहीं जाता)। दूसरे रास्ते से जाँचना (फ़ोन करना, खुद साइट पर जाना) फ़िशिंग को नाकाम करता है।", "يسأل curl منارة اللعبة على 127.0.0.1 (لا شيء يخرج من الحاسوب). التحقق عبر قناة أخرى (الاتصال، الذهاب إلى الموقع بنفسك) يُفشل التصيّد.", "curl খেলার 127.0.0.1-এর বাতিঘরকে জিজ্ঞেস করে (কিছুই কম্পিউটারের বাইরে যায় না)। অন্য পথে যাচাই (ফোন করা, নিজে সাইটে যাওয়া) ফিশিং ব্যর্থ করে।", "curl bertanya ke mercusuar permainan di 127.0.0.1 (tak ada yang keluar dari komputer). Memeriksa lewat saluran lain (menelepon, membuka situs sendiri) menggagalkan phishing.", "curl کھیل کے 127.0.0.1 والے لائٹ ہاؤس سے پوچھتا ہے (کچھ بھی کمپیوٹر سے باہر نہیں جاتا)۔ دوسرے راستے سے جانچنا (فون کرنا، خود سائٹ پر جانا) فشنگ کو ناکام کرتا ہے۔"),
 "hist.cit11.2.dit": T("Le gardien a noté 6 remarques sur la fausse lettre. Lis-les.", "The guard wrote 6 remarks about the fake letter. Read them.", "El guardián anotó 6 observaciones sobre la carta falsa. Léelas.", "Der Wächter hat 6 Bemerkungen zum falschen Brief notiert. Lies sie.", "Il guardiano ha annotato 6 osservazioni sulla lettera falsa. Leggile.", "O guardião anotou 6 observações sobre a carta falsa. Leia.", "Страж записал 6 замечаний о фальшивом письме. Прочитай их.", "守卫记下了 6 条关于假信的观察。读一读。", "守り手がニセの手紙について6つのメモを書いた。読もう。", "पहरेदार ने नकली चिट्ठी पर 6 बातें लिखीं। पढ़ो।", "دوّن الحارس 6 ملاحظات عن الرسالة المزيفة. اقرأها.", "পাহারাদার নকল চিঠি নিয়ে ৬টা কথা লিখেছে। পড়ো।", "Penjaga mencatat 6 hal tentang surat palsu. Bacalah.", "پہرے دار نے جعلی خط پر 6 باتیں لکھیں۔ پڑھو۔"),
 "hist.cit11.2.bravo": T("Trois sont de vrais indices de piège, trois ne prouvent rien. Lesquels ?", "Three are real signs of a trap, three prove nothing. Which ones?", "Tres son pistas reales de trampa, tres no prueban nada. ¿Cuáles?", "Drei sind echte Fallen-Hinweise, drei beweisen nichts. Welche?", "Tre sono veri indizi di trappola, tre non provano nulla. Quali?", "Três são pistas reais de armadilha, três não provam nada. Quais?", "Три — настоящие признаки ловушки, три ничего не доказывают. Какие?", "其中三条是陷阱的真线索，三条什么也证明不了。是哪几条？", "3つは本当のわなのしるし、3つは何の証拠にもならない。どれ？", "तीन जाल के असली सुराग हैं, तीन कुछ साबित नहीं करते। कौन से?", "ثلاث منها علامات فخ حقيقية، وثلاث لا تثبت شيئًا. أيّها؟", "তিনটা আসল ফাঁদের চিহ্ন, তিনটা কিছুই প্রমাণ করে না। কোনগুলো?", "Tiga adalah tanda jebakan sungguhan, tiga tak membuktikan apa-apa. Yang mana?", "تین جال کے اصل سراغ ہیں، تین کچھ ثابت نہیں کرتے۔ کون سے؟"),
 "hist.cit11.2.adulte": T("Indices classiques d'hameçonnage : urgence ou menace, demande de secret, adresse ou lien qui ne correspond pas. La mise en forme ou l'heure n'en sont pas.", "Classic phishing signs: urgency or threat, a request for a secret, an address or link that doesn't match. Layout or time are not signs.", "Pistas clásicas de phishing: urgencia o amenaza, petición de un secreto, dirección o enlace que no corresponde. El formato o la hora no lo son.", "Klassische Phishing-Zeichen: Dringlichkeit oder Drohung, Bitte um ein Geheimnis, Adresse oder Link, die nicht passen. Layout oder Uhrzeit sind keine.", "Indizi classici di phishing: urgenza o minaccia, richiesta di un segreto, indirizzo o link che non corrisponde. L'impaginazione o l'ora non lo sono.", "Sinais clássicos de phishing: urgência ou ameaça, pedido de segredo, endereço ou link que não bate. O visual ou a hora não são.", "Классические признаки фишинга: срочность или угроза, просьба о секрете, несовпадающий адрес или ссылка. Оформление или время — не признаки.", "钓鱼的典型迹象：催促或威胁、索要秘密、对不上的地址或链接。排版和时间不算。", "フィッシングの典型的なしるし：急がせる・おどす、秘密を聞く、合わないアドレスやリンク。見た目や時刻はしるしではない。", "फ़िशिंग के आम सुराग: जल्दबाज़ी या धमकी, राज़ माँगना, मेल न खाता पता या लिंक। बनावट या समय सुराग नहीं।", "علامات التصيّد المعتادة: الاستعجال أو التهديد، طلب سر، عنوان أو رابط لا يتطابق. التنسيق أو الوقت ليسا علامة.", "ফিশিংয়ের সাধারণ চিহ্ন: তাড়াহুড়ো বা হুমকি, গোপন কথা চাওয়া, না-মেলা ঠিকানা বা লিংক। সাজসজ্জা বা সময় চিহ্ন নয়।", "Tanda phishing klasik: desakan atau ancaman, permintaan rahasia, alamat atau tautan yang tak cocok. Tata letak atau jam bukan tanda.", "فشنگ کے عام سراغ: جلدی یا دھمکی، راز مانگنا، نہ ملتا پتا یا لنک۔ بناوٹ یا وقت سراغ نہیں۔"),
 "hist.cit11.3.dit": T("Donne les numéros des 3 vrais indices (remplace les ? par les numéros).", "Give the numbers of the 3 real signs (replace the ? with the numbers).", "Da los números de las 3 pistas reales (cambia los ? por los números).", "Gib die Nummern der 3 echten Hinweise an (ersetze die ? durch die Nummern).", "Dai i numeri dei 3 veri indizi (sostituisci i ? con i numeri).", "Dê os números das 3 pistas reais (troque os ? pelos números).", "Назови номера 3 настоящих признаков (замени ? на номера).", "给出 3 条真线索的编号（把 ? 换成编号）。", "本当のしるし3つの番号を答えよう（? を番号に変えて）。", "3 असली सुरागों के नंबर दो (? की जगह नंबर)।", "أعطِ أرقام العلامات الحقيقية الثلاث (استبدل ? بالأرقام).", "৩টা আসল চিহ্নের নম্বর দাও (? এর জায়গায় নম্বর)।", "Berikan nomor 3 tanda yang benar (ganti ? dengan nomornya).", "3 اصل سراغوں کے نمبر دو (? کی جگہ نمبر)۔"),
 "hist.cit11.3.bravo": T("Bravo, le faux facteur est démasqué : il redevient une ombre. Jamais de mot de passe par lettre !", "Well done, the fake mail carrier is unmasked: he turns back into a shadow. Never a password by letter!", "¡Bravo, el falso cartero está desenmascarado: vuelve a ser una sombra! ¡Nunca una contraseña por carta!", "Bravo, der falsche Briefträger ist entlarvt: Er wird wieder zum Schatten. Nie ein Passwort per Brief!", "Bravo, il falso postino è smascherato: torna un'ombra. Mai una password per lettera!", "Muito bem, o falso carteiro foi desmascarado: vira uma sombra. Nunca senha por carta!", "Браво, фальшивый почтальон разоблачён: он снова стал тенью. Никогда не отправляй пароль в письме!", "真棒，假邮差被识破了，又变回一团影子。永远不要在信里给密码！", "おみごと、ニセの郵便屋さんの正体がばれて、影にもどった。手紙でパスワードは決してわたさない！", "शाबाश, नकली डाकिया पकड़ा गया: वह फिर परछाईं बन गया। चिट्ठी से कभी पासवर्ड नहीं!", "أحسنت، انكشف ساعي البريد المزيف: عاد ظلًا. لا كلمة مرور في رسالة أبدًا!", "শাবাশ, নকল ডাকপিয়ন ধরা পড়েছে: আবার ছায়া হয়ে গেছে। চিঠিতে কখনো পাসওয়ার্ড নয়!", "Hebat, tukang pos palsu ketahuan: ia kembali jadi bayangan. Jangan pernah kata sandi lewat surat!", "شاباش، جعلی ڈاکیا پکڑا گیا: وہ پھر سایہ بن گیا۔ خط سے کبھی پاس ورڈ نہیں!"),
 "hist.cit11.3.adulte": T("Aucun service sérieux ne demande un mot de passe par message. En cas de doute : ne pas cliquer, vérifier par un autre canal, prévenir un adulte.", "No serious service asks for a password by message. If in doubt: don't click, check through another channel, tell an adult.", "Ningún servicio serio pide una contraseña por mensaje. Ante la duda: no hagas clic, comprueba por otro canal, avisa a un adulto.", "Kein seriöser Dienst fragt per Nachricht nach einem Passwort. Im Zweifel: nicht klicken, über einen anderen Weg prüfen, einem Erwachsenen Bescheid sagen.", "Nessun servizio serio chiede una password per messaggio. Nel dubbio: non cliccare, verifica per un altro canale, avvisa un adulto.", "Nenhum serviço sério pede senha por mensagem. Na dúvida: não clique, confira por outro canal, avise um adulto.", "Ни один серьёзный сервис не просит пароль в сообщении. Если сомневаешься: не нажимай, проверь другим путём, скажи взрослому.", "正经的服务从不通过消息要密码。拿不准时：别点，换个渠道核实，告诉大人。", "ちゃんとしたサービスは、メッセージでパスワードを聞かない。迷ったら：クリックしない、別の道で確かめる、大人に知らせる。", "कोई भी भरोसेमंद सेवा संदेश से पासवर्ड नहीं माँगती। शक हो तो: क्लिक मत करो, दूसरे रास्ते से जाँचो, किसी बड़े को बताओ।", "لا خدمة جادة تطلب كلمة مرور عبر رسالة. عند الشك: لا تنقر، تحقق عبر قناة أخرى، أخبر شخصًا بالغًا.", "কোনো ভালো পরিষেবা বার্তায় পাসওয়ার্ড চায় না। সন্দেহ হলে: ক্লিক কোরো না, অন্য পথে যাচাই করো, বড় কাউকে জানাও।", "Tak ada layanan serius yang meminta kata sandi lewat pesan. Jika ragu: jangan klik, periksa lewat saluran lain, beri tahu orang dewasa.", "کوئی سنجیدہ سروس پیغام سے پاس ورڈ نہیں مانگتی۔ شک ہو تو: کلک نہ کرو، دوسرے راستے سے جانچو، کسی بڑے کو بتاؤ۔"),
}
